/// Maximum number of identifiers accepted by one storage bulk-read call.
///
/// Bulk readers bind one canonical JSON array rather than one SQLite variable
/// per identifier, so this is an allocation and latency bound rather than a
/// database parameter limit.  Callers that need more must page deliberately.
pub const STORAGE_BULK_ID_INPUT_MAX: usize = 4_096;

/// Maximum number of downstream-delivery leases changed by one atomic batch.
pub const EVENT_DELIVERY_LEASE_BULK_MAX: usize = 64;
/// Maximum UTF-8 bytes accepted for one event-delivery ownership token.
/// Production tokens are currently 79 ASCII bytes; the wider ceiling leaves
/// room for a future format without allowing a public bulk call to clone,
/// sort, and JSON-encode attacker-sized strings.
pub const EVENT_DELIVERY_LEASE_TOKEN_MAX_BYTES: usize = 256;
/// Maximum UTF-8 bytes persisted as one event-delivery status label.
pub const EVENT_DELIVERY_STATUS_MAX_BYTES: usize = 256;
/// Maximum UTF-8 bytes persisted as one event-delivery workflow identity.
pub const EVENT_DELIVERY_WORKFLOW_ID_MAX_BYTES: usize = 1_024;

// Keep hot-path SQL in one place so execution and EXPLAIN-plan regression
// tests cannot silently drift apart.
const QUERY_UNHANDLED_EVENTS_NEWEST_SQL: &str = r"SELECT id, pane_id, rule_id, agent_type, event_type, severity, confidence,
     extracted, matched_text, segment_id, detected_at, dedupe_key, handled_at,
     handled_by_workflow_id, handled_status
     FROM events
     WHERE handled_at IS NULL
     ORDER BY detected_at DESC, id DESC
     LIMIT ?1";

const QUERY_UNHANDLED_EVENT_COUNTS_SQL: &str = r"SELECT pane_id, COUNT(*) AS cnt
      FROM events
      WHERE handled_at IS NULL
      GROUP BY pane_id";

const QUERY_UNHANDLED_EVENT_COUNTS_BULK_SQL: &str = r"WITH requested(pane_id) AS (
         SELECT CAST(requested_json.value AS INTEGER)
         FROM json_each(?1) AS requested_json
         WHERE requested_json.type = 'integer'
     )
     SELECT requested.pane_id,
            (
                SELECT COUNT(*)
                FROM events
                WHERE events.handled_at IS NULL
                  AND events.pane_id = requested.pane_id
            )
     FROM requested";

const QUERY_PANE_LAST_OUTPUT_AT_SQL: &str = r"SELECT captured_at
      FROM output_segments
      WHERE pane_id = ?1
      ORDER BY captured_at DESC
      LIMIT 1";

const QUERY_PANE_LAST_OUTPUT_AT_BULK_SQL: &str = r"WITH requested(pane_id) AS (
         SELECT CAST(requested_json.value AS INTEGER)
         FROM json_each(?1) AS requested_json
         WHERE requested_json.type = 'integer'
     )
     SELECT panes.pane_id,
            (
                SELECT output_segments.captured_at
                FROM output_segments
                WHERE output_segments.pane_id = panes.pane_id
                ORDER BY output_segments.captured_at DESC
                LIMIT 1
     )
     FROM requested
     JOIN panes ON panes.pane_id = requested.pane_id";

const QUERY_LAST_ACTIVITY_BY_PANE_SQL: &str = r"SELECT panes.pane_id,
              (
                  SELECT output_segments.captured_at
                  FROM output_segments
                  WHERE output_segments.pane_id = panes.pane_id
                  ORDER BY output_segments.captured_at DESC
                  LIMIT 1
              )
       FROM panes
       ORDER BY panes.pane_id ASC";

const FINALIZE_EVENT_DELIVERY_LEASES_BULK_SQL: &str = r"WITH requested(event_id, token) AS (
         SELECT CAST(json_extract(lease_json.value, '$[0]') AS INTEGER),
                json_extract(lease_json.value, '$[1]')
         FROM json_each(?1) AS lease_json
         WHERE json_type(lease_json.value, '$[0]') = 'integer'
           AND json_type(lease_json.value, '$[1]') = 'text'
     )
     UPDATE events
     SET handled_at = ?2,
         handled_by_workflow_id = ?3,
         handled_status = ?4,
         delivery_lease_token = NULL,
         delivery_lease_acquired_at = NULL,
         delivery_lease_expires_at = NULL
     WHERE handled_at IS NULL
       AND (id, delivery_lease_token) IN (
           SELECT requested.event_id, requested.token FROM requested
       )
     RETURNING id";

const RELEASE_EVENT_DELIVERY_LEASES_BULK_SQL: &str = r"WITH requested(event_id, token) AS (
         SELECT CAST(json_extract(lease_json.value, '$[0]') AS INTEGER),
                json_extract(lease_json.value, '$[1]')
         FROM json_each(?1) AS lease_json
         WHERE json_type(lease_json.value, '$[0]') = 'integer'
           AND json_type(lease_json.value, '$[1]') = 'text'
     )
     UPDATE events
     SET delivery_lease_token = NULL,
         delivery_lease_acquired_at = NULL,
         delivery_lease_expires_at = NULL
     WHERE handled_at IS NULL
       AND (id, delivery_lease_token) IN (
           SELECT requested.event_id, requested.token FROM requested
       )
     RETURNING id";

