    #[test]
    fn writer_io_gate_routes_full_rebuild_as_lower_priority_index_work() {
        let mut gate = tiny_writer_gate();
        let incremental = fts_sync_command(1, 256);
        let rebuild = fts_rebuild_command(1, 256);

        let (incremental_id, incremental_decision) = gate.admit_command(&incremental).unwrap();
        let (rebuild_id, rebuild_decision) = gate.admit_command(&rebuild).unwrap();

        assert_eq!(incremental_decision.class, StorageIoClass::FtsIncremental);
        assert_eq!(rebuild_decision.class, StorageIoClass::FtsRebuild);
        assert!(incremental_decision.outcome.accepted());
        assert!(rebuild_decision.outcome.accepted());

        let first = gate.pop_next().unwrap();
        let second = gate.pop_next().unwrap();

        assert_eq!(first.item.id, incremental_id);
        assert_eq!(first.item.class, StorageIoClass::FtsIncremental);
        assert_eq!(second.item.id, rebuild_id);
        assert_eq!(second.item.class, StorageIoClass::FtsRebuild);
    }

    #[test]
    fn writer_io_gate_clears_ordering_sequences_after_batch_finishes() {
        let mut gate = tiny_writer_gate();
        let segment = segment_command(11, "first segment");
        let gap = gap_command(12, "capture gap");

        let (_, segment_decision) = gate.admit_command(&segment).unwrap();
        let (_, gap_decision) = gate.admit_command(&gap).unwrap();

        assert!(segment_decision.outcome.accepted());
        assert!(gap_decision.outcome.accepted());
        assert_eq!(gate.next_ordering_sequence_by_stream.len(), 2);

        while gate.pop_next().is_some() {}
        gate.finish_batch();

        assert!(gate.next_ordering_sequence_by_stream.is_empty());

        let next_segment = segment_command(11, "new batch segment");
        let (next_id, next_decision) = gate.admit_command(&next_segment).unwrap();
        assert!(next_decision.outcome.accepted());
        let dispatched = gate.pop_next().unwrap();
        assert_eq!(next_id, 1, "empty batches reset the bounded work-ID epoch");
        assert_eq!(dispatched.item.id, next_id);
        let ordering = dispatched.item.ordering.unwrap();
        assert_eq!(ordering.stream, "pane:11");
        assert_eq!(ordering.sequence, 0);
    }

    #[test]
    fn writer_io_gate_recovery_resets_the_bounded_work_id_epoch() {
        let mut gate = tiny_writer_gate();
        gate.next_work_id = u64::MAX;
        gate.reset_after_panic();
        assert_eq!(gate.next_work_id, 1);

        gate.next_work_id = u64::MAX;
        gate.reset_after_scheduler_loss();
        assert_eq!(gate.next_work_id, 1);
    }

