    #[test]
    fn singleton_append_failure_after_retroactive_mask_restores_database_and_redactor() {
        let backend = real_writer_backend_with_panes(&[71]);
        let mut redactors = HashMap::<u64, SegmentPersistRedactor>::new();
        append_segment_commit_backend(&backend, 71, "prefix sk-", None, None, &mut redactors)
            .expect("seed split-secret prefix");
        let redactors_before = redactors.clone();

        set_append_commit_fault_for_test(AppendCommitFaultForTest::SingletonAfterRedaction);
        let error = match append_segment_commit_backend(
            &backend,
            71,
            "abcdefghijklmnopqrstuvwxyz suffix",
            None,
            None,
            &mut redactors,
        ) {
            Ok(_) => panic!("post-redaction singleton fault must roll back"),
            Err(error) => error,
        };

        assert!(
            matches!(&error, crate::Error::Storage(StorageError::Database(_))),
            "a proven ordinary rollback remains an ordinary database error: {error}"
        );
        assert_eq!(
            sorted_segment_contents(&backend, 71),
            vec!["prefix sk-".to_string()],
            "ROLLBACK must restore the prior row rewritten by retroactive masking and remove the new row"
        );
        assert_eq!(
            redactors, redactors_before,
            "ordinary rollback must restore the exact pre-transaction lookback"
        );

        append_segment_commit_backend(
            &backend,
            71,
            "abcdefghijklmnopqrstuvwxyz suffix",
            None,
            None,
            &mut redactors,
        )
        .expect("one-shot fault clears and restored lookback supports retry");
        let persisted = sorted_segment_contents(&backend, 71).concat();
        assert!(!persisted.contains("sk-abcdefghijklmnopqrstuvwxyz"));
        assert!(persisted.contains(crate::redactor::REDACTED_MARKER));
    }

    #[test]
    fn grouped_second_append_failure_restores_all_unique_redactors_and_rows() {
        let backend = real_writer_backend_with_panes(&[81, 82]);
        let mut redactors = HashMap::<u64, SegmentPersistRedactor>::new();
        for pane_id in [81, 82] {
            append_segment_commit_backend(
                &backend,
                pane_id,
                "prefix sk-",
                None,
                None,
                &mut redactors,
            )
            .expect("seed grouped split-secret prefix");
        }
        let redactors_before = redactors.clone();
        let (first_tx, _first_rx) = oneshot::channel();
        let (second_tx, _second_rx) = oneshot::channel();
        let writes = vec![
            PendingAppendSegmentWrite {
                pane_id: 81,
                content: "abcdefghijklmnopqrstuvwxyz first".to_string(),
                content_hash: None,
                zone_type: None,
                capture_hold: None,
                respond: WriterResultResponder::new(first_tx),
            },
            PendingAppendSegmentWrite {
                pane_id: 82,
                content: "abcdefghijklmnopqrstuvwxyz second".to_string(),
                content_hash: None,
                zone_type: None,
                capture_hold: None,
                respond: WriterResultResponder::new(second_tx),
            },
        ];

        set_append_commit_fault_for_test(AppendCommitFaultForTest::GroupAfterRedaction(1));
        let error = match append_segment_group_commit_backend(&backend, &writes, &mut redactors) {
            Ok(_) => panic!("fault after the second redactor mutation must roll back the group"),
            Err(error) => error,
        };

        assert!(
            matches!(&error, crate::Error::Storage(StorageError::Database(_))),
            "a proven ordinary grouped rollback remains a database error: {error}"
        );
        for pane_id in [81, 82] {
            assert_eq!(
                sorted_segment_contents(&backend, pane_id),
                vec!["prefix sk-".to_string()],
                "group rollback must restore rewritten prior rows and remove every new row for pane {pane_id}"
            );
        }
        assert_eq!(
            redactors, redactors_before,
            "group rollback must restore one exact snapshot per uniquely touched pane"
        );
    }

    #[test]
    fn writer_batch_group_commits_consecutive_append_segments_same_pane() {
        run_storage_async_test(async {
            let backend = crate::storage_backend_trait::MockBackend::new();
            // FIFO of query_row_typed responses for the grouped append path. Each
            // segment now also runs a best-effort `segment_embeddings` insert
            // (ft-xx5cl) via `execute_typed` -> `query_row_typed`, which consumes
            // one response per segment; the embedding rows are `None` (return
            // value ignored). Order: next_seq, insert#1, embed#1, insert#2,
            // embed#2 (the same-pane second next_seq is served from the cache).
            backend.enqueue_row_response(Some(vec!["0".to_string()])); // next_seq
            backend.enqueue_row_response(Some(vec!["101".to_string()])); // insert #1
            backend.enqueue_row_response(None); // embed #1 (ignored)
            backend.enqueue_row_response(Some(vec!["102".to_string()])); // insert #2
            backend.enqueue_row_response(None); // embed #2 (ignored)

            let mut gate = StorageIoWriterGate::default();
            let mut should_break = false;
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();
            let (first_tx, first_rx) = oneshot::channel();
            let (second_tx, second_rx) = oneshot::channel();
            let mut batch = VecDeque::new();
            batch.push_back(WriteCommand::AppendSegment {
                pane_id: 77,
                content: "first group append".to_string(),
                content_hash: Some("hash-first".to_string()),
                zone_type: None,
                capture_hold: None,
                respond: first_tx,
            });
            batch.push_back(WriteCommand::AppendSegment {
                pane_id: 77,
                content: "second group append".to_string(),
                content_hash: None,
                zone_type: None,
                capture_hold: None,
                respond: second_tx,
            });
            let interruption = dispatch_write_command_batch(
                &backend,
                batch,
                &mut should_break,
                &mut mmap_mirror,
                &mut segment_redactors,
                &mut gate,
                false,
            );

            assert!(interruption.is_none());
            assert!(!should_break);
            let first = crate::runtime_async::oneshot_recv(first_rx)
                .await
                .expect("first append response should arrive")
                .expect("first grouped append should succeed");
            let second = crate::runtime_async::oneshot_recv(second_rx)
                .await
                .expect("second append response should arrive")
                .expect("second grouped append should succeed");

            assert_eq!(first.id, 101);
            assert_eq!(first.pane_id, 77);
            assert_eq!(first.seq, 0);
            assert_eq!(first.content, "first group append");
            assert_eq!(first.content_hash.as_deref(), Some("hash-first"));
            assert_eq!(second.id, 102);
            assert_eq!(second.pane_id, 77);
            assert_eq!(second.seq, 1);
            assert_eq!(second.content, "second group append");

            let executed = backend.executed();
            assert_eq!(
                executed,
                vec!["BEGIN".to_string(), "COMMIT".to_string()],
                "grouped append dispatch must use one explicit transaction"
            );
            let writer_queries = backend.observed_queries();
            let next_seq_queries = writer_queries
                .iter()
                .filter(|(sql, params)| {
                    sql.contains("SELECT COALESCE(MAX(seq) + 1, 0)")
                        && params == &vec!["77".to_string()]
                })
                .count();
            let insert_queries = writer_queries
                .iter()
                .filter(|(sql, _)| sql.contains("INSERT INTO output_segments"))
                .count();
            assert_eq!(
                next_seq_queries, 1,
                "same-pane group should query the starting seq once; got {writer_queries:?}"
            );
            assert_eq!(
                insert_queries, 2,
                "both grouped segments should insert inside the transaction; got {writer_queries:?}"
            );
        });
    }

    #[test]
    fn writer_batch_group_commit_mismatched_result_count_fails_all_callers() {
        run_storage_async_test(async {
            let (first_tx, first_rx) = oneshot::channel();
            let (second_tx, second_rx) = oneshot::channel();
            let group = vec![
                PendingAppendSegmentWrite {
                    pane_id: 77,
                    content: "first mismatched group append".to_string(),
                    content_hash: None,
                    zone_type: None,
                    capture_hold: None,
                    respond: WriterResultResponder::new(first_tx),
                },
                PendingAppendSegmentWrite {
                    pane_id: 77,
                    content: "second mismatched group append".to_string(),
                    content_hash: None,
                    zone_type: None,
                    capture_hold: None,
                    respond: WriterResultResponder::new(second_tx),
                },
            ];
            let committed = vec![CommittedAppendSegment {
                segment: Segment {
                    id: 501,
                    pane_id: 77,
                    seq: 0,
                    content: "first mismatched group append".to_string(),
                    content_len: "first mismatched group append".len(),
                    content_hash: None,
                    captured_at: 123,
                },
                retained_tail_moved: false,
            }];
            let mut mmap_mirror = None;

            dispatch_append_segment_group_commit_result(Ok(committed), group, &mut mmap_mirror);

            let first_result = crate::runtime_async::oneshot_recv(first_rx)
                .await
                .expect("first grouped append should receive a mismatch error");
            let first_error = first_result.expect_err("first grouped append should fail closed");
            assert!(
                first_error
                    .to_string()
                    .contains("returned 1 committed segments for 2 pending appends"),
                "{first_error}"
            );
            let second_result = crate::runtime_async::oneshot_recv(second_rx)
                .await
                .expect("second grouped append should receive a mismatch error");
            let second_error = second_result.expect_err("second grouped append should fail closed");
            assert!(
                second_error
                    .to_string()
                    .contains("returned 1 committed segments for 2 pending appends"),
                "{second_error}"
            );
        });
    }

