    struct RawMutationPanicBackend {
        inner: crate::storage_backend_trait::MockBackend,
        calls: Mutex<Vec<&'static str>>,
        mutation_count: AtomicUsize,
        panic_started: AtomicBool,
        post_panic_calls: AtomicUsize,
    }

    impl RawMutationPanicBackend {
        fn new() -> Self {
            Self {
                inner: crate::storage_backend_trait::MockBackend::new(),
                calls: Mutex::new(Vec::new()),
                mutation_count: AtomicUsize::new(0),
                panic_started: AtomicBool::new(false),
                post_panic_calls: AtomicUsize::new(0),
            }
        }

        fn note_call(&self, label: &'static str) {
            if self.panic_started.load(AtomicOrdering::Acquire) {
                self.post_panic_calls.fetch_add(1, AtomicOrdering::Relaxed);
            }
            self.calls
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .push(label);
        }

        fn calls(&self) -> Vec<&'static str> {
            self.calls
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .clone()
        }
    }

    impl StorageBackend for RawMutationPanicBackend {
        fn execute(&self, sql: &str) -> std::result::Result<usize, BackendError> {
            self.note_call("execute");
            self.inner.execute(sql)
        }

        fn execute_batch(&self, sql: &str) -> std::result::Result<(), BackendError> {
            self.note_call("execute_batch");
            self.inner.execute_batch(sql)
        }

        fn set_busy_timeout(
            &self,
            timeout: std::time::Duration,
        ) -> std::result::Result<(), BackendError> {
            self.note_call("set_busy_timeout");
            self.inner.set_busy_timeout(timeout)
        }

        fn query_scalar(&self, sql: &str) -> std::result::Result<Option<String>, BackendError> {
            self.note_call("query_scalar");
            self.inner.query_scalar(sql)
        }

        fn transaction_state(&self) -> std::result::Result<BackendTransactionState, BackendError> {
            self.note_call("transaction_state");
            self.inner.transaction_state()
        }

        fn begin_transaction(
            &self,
        ) -> std::result::Result<crate::storage_backend_trait::TransactionGuard<'_>, BackendError>
        {
            self.note_call("begin_transaction");
            self.inner.begin_transaction()
        }

        fn user_version(&self) -> std::result::Result<u32, BackendError> {
            self.note_call("user_version");
            self.inner.user_version()
        }

        fn set_user_version(&self, version: u32) -> std::result::Result<(), BackendError> {
            self.note_call("set_user_version");
            self.inner.set_user_version(version)
        }

        fn backend_name(&self) -> &'static str {
            "raw_mutation_panic"
        }

        fn query_row_strings(
            &self,
            sql: &str,
            params: &[&str],
        ) -> std::result::Result<Option<Vec<String>>, BackendError> {
            if sql.contains("UPDATE events SET handled_at") {
                {
                    self.calls
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .push("raw_mutation_then_panic");
                }
                self.mutation_count.fetch_add(1, AtomicOrdering::Relaxed);
                self.panic_started.store(true, AtomicOrdering::Release);
                std::panic::panic_any("INJECTED-RAW-BACKEND-MUTATION-PANIC");
            }
            self.note_call("query_row_strings");
            self.inner.query_row_strings(sql, params)
        }

        fn query_map_strings(
            &self,
            sql: &str,
            params: &[&str],
        ) -> std::result::Result<Vec<Vec<String>>, BackendError> {
            self.note_call("query_map_strings");
            self.inner.query_map_strings(sql, params)
        }

        fn execute_many(
            &self,
            sql: &str,
            param_rows: &[Vec<ToSqlValue<'_>>],
        ) -> std::result::Result<usize, BackendError> {
            self.note_call("execute_many");
            self.inner.execute_many(sql, param_rows)
        }
    }

    #[test]
    fn writer_batch_group_commit_panic_rolls_back_open_transaction() {
        let _counter_guard = writer_panic_counter_test_lock();
        reset_storage_writer_panics_total_for_test();

        run_storage_async_test(async {
            let backend = PanicOnQueryBackend::new();
            let mut gate = StorageIoWriterGate::default();
            let mut should_break = false;
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();
            let (first_tx, first_rx) = oneshot::channel();
            let (second_tx, second_rx) = oneshot::channel();
            let (routed_tail_tx, routed_tail_rx) = oneshot::channel();
            let (barrier_tail_tx, barrier_tail_rx) = oneshot::channel();
            let mut batch = VecDeque::new();
            batch.push_back(WriteCommand::AppendSegment {
                pane_id: 77,
                content: "first panic group append".to_string(),
                content_hash: None,
                zone_type: None,
                capture_hold: None,
                respond: first_tx,
            });
            batch.push_back(WriteCommand::AppendSegment {
                pane_id: 77,
                content: "second panic group append".to_string(),
                content_hash: None,
                zone_type: None,
                capture_hold: None,
                respond: second_tx,
            });
            batch.push_back(WriteCommand::RecordEvent {
                event: StoredEvent {
                    id: 0,
                    pane_id: 77,
                    rule_id: "panic-tail-event".to_string(),
                    agent_type: "test".to_string(),
                    event_type: "panic.tail".to_string(),
                    severity: "info".to_string(),
                    confidence: 1.0,
                    extracted: None,
                    matched_text: None,
                    segment_id: None,
                    detected_at: 1,
                    dedupe_key: None,
                    handled_at: None,
                    handled_by_workflow_id: None,
                    handled_status: None,
                },
                capture_hold: None,
                respond: routed_tail_tx,
            });
            batch.push_back(WriteCommand::MarkEventHandled {
                event_id: 42,
                workflow_id: None,
                status: "panic-tail-barrier".to_string(),
                respond: barrier_tail_tx,
            });

            let interruption = dispatch_write_command_batch(
                &backend,
                batch,
                &mut should_break,
                &mut mmap_mirror,
                &mut segment_redactors,
                &mut gate,
                false,
            );

            assert!(
                interruption
                    .as_ref()
                    .is_some_and(|interruption| interruption.terminate_epoch)
            );
            assert!(should_break);
            assert_eq!(storage_writer_panics_total(), 1);
            assert_eq!(
                backend.executed(),
                vec!["BEGIN".to_string(), "ROLLBACK".to_string()],
                "append-group panic recovery must close the open transaction"
            );

            let first_result = crate::runtime_async::oneshot_recv(first_rx)
                .await
                .expect("first grouped append should receive a recovered panic error");
            let first_error = first_result.expect_err("first grouped append should fail closed");
            assert!(matches!(
                &first_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            assert!(!first_error.to_string().contains("SECRET-APPEND-SENTINEL"));
            let second_result = crate::runtime_async::oneshot_recv(second_rx)
                .await
                .expect("second grouped append should receive a recovered panic error");
            let second_error = second_result.expect_err("second grouped append should fail closed");
            assert!(matches!(
                &second_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            assert!(!second_error.to_string().contains("SECRET-APPEND-SENTINEL"));

            let routed_tail_result = crate::runtime_async::oneshot_recv(routed_tail_rx)
                .await
                .expect("routed command that forced the append flush should receive an error");
            let routed_tail_error =
                routed_tail_result.expect_err("routed flush tail must fail closed");
            assert!(matches!(
                routed_tail_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));

            let barrier_tail_result = crate::runtime_async::oneshot_recv(barrier_tail_rx)
                .await
                .expect("barrier command after the failed routed flush should receive an error");
            let barrier_tail_error =
                barrier_tail_result.expect_err("barrier flush tail must fail closed");
            assert!(matches!(
                barrier_tail_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
        });
    }

    #[test]
    fn writer_batch_makes_every_raw_dispatch_panic_terminal_and_fails_tail() {
        let _counter_guard = writer_panic_counter_test_lock();
        reset_storage_writer_panics_total_for_test();

        run_storage_async_test(async {
            let backend = RusqliteBackend::new(rusqlite::Connection::open_in_memory().unwrap());
            let mut gate = tiny_writer_gate();
            let mut should_break = false;
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();
            let (panic_tx, panic_rx) = oneshot::channel();
            let (tail_tx, tail_rx) = oneshot::channel();
            let (reserve_tx, reserve_rx) = oneshot::channel();
            let (finalize_tx, finalize_rx) = oneshot::channel();
            let (release_tx, release_rx) = oneshot::channel();
            let mut batch = VecDeque::new();
            batch.push_back(WriteCommand::PanicForTest {
                message: "PANIC-PAYLOAD-SECRET-DISPATCH-SENTINEL",
                respond: panic_tx,
            });
            batch.push_back(WriteCommand::MarkEventHandled {
                event_id: 42,
                workflow_id: None,
                status: "handled".to_string(),
                respond: tail_tx,
            });
            batch.push_back(WriteCommand::ReserveEventDelivery {
                event_id: 42,
                token: "reserve-tail".to_string(),
                ttl_ms: 1_000,
                respond: reserve_tx,
            });
            batch.push_back(WriteCommand::FinalizeEventDelivery {
                event_id: 42,
                token: "finalize-tail".to_string(),
                workflow_id: None,
                status: "delivered".to_string(),
                respond: finalize_tx,
            });
            batch.push_back(WriteCommand::ReleaseEventDelivery {
                event_id: 42,
                token: "release-tail".to_string(),
                respond: release_tx,
            });

            let interruption = dispatch_write_command_batch(
                &backend,
                batch,
                &mut should_break,
                &mut mmap_mirror,
                &mut segment_redactors,
                &mut gate,
                false,
            );

            assert!(
                interruption
                    .as_ref()
                    .is_some_and(|interruption| interruption.terminate_epoch)
            );
            assert!(should_break);
            assert_eq!(storage_writer_panics_total(), 1);
            assert_eq!(gate.scheduler.aggregate_items(), 0);
            assert!(gate.next_ordering_sequence_by_stream.is_empty());
            let panic_result = crate::runtime_async::oneshot_recv(panic_rx)
                .await
                .expect("panicking command should receive a typed panic error");
            let panic_error = panic_result.expect_err("panicking command should fail closed");
            assert!(matches!(
                &panic_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            assert!(!panic_error.to_string().contains("SECRET-DISPATCH-SENTINEL"));
            let tail_result = crate::runtime_async::oneshot_recv(tail_rx)
                .await
                .expect("undispatched tail command should receive a panic error");
            let tail_error = tail_result.expect_err("tail command should fail closed");
            assert!(matches!(
                tail_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            let reserve_result = crate::runtime_async::oneshot_recv(reserve_rx)
                .await
                .expect("undispatched reserve should receive a panic error");
            let reserve_error =
                reserve_result.expect_err("undispatched reserve should fail closed");
            assert!(matches!(
                reserve_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            let finalize_result = crate::runtime_async::oneshot_recv(finalize_rx)
                .await
                .expect("undispatched finalize should receive a panic error");
            let finalize_error =
                finalize_result.expect_err("undispatched finalize should fail closed");
            assert!(matches!(
                finalize_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
            let release_result = crate::runtime_async::oneshot_recv(release_rx)
                .await
                .expect("undispatched release should receive a panic error");
            let release_error =
                release_result.expect_err("undispatched release should fail closed");
            assert!(matches!(
                release_error,
                crate::Error::Storage(StorageError::WriterBackendEpochPoisoned)
            ));
        });
    }

    #[test]
    fn raw_backend_mutation_panic_stops_all_later_backend_and_adaptive_work() {
        let _counter_guard = writer_panic_counter_test_lock();
        reset_storage_writer_panics_total_for_test();

        run_storage_async_test(async {
            let backend = RawMutationPanicBackend::new();
            let (raw_tx, mut rx) = mpsc::channel::<WriteCommand>(8);
            let sender = WriteCommandSender::new(raw_tx, 8);
            let terminal_state = Arc::clone(&sender.terminal_state);
            let terminal_admission_gate = Arc::clone(&sender.terminal_admission_gate);
            let queued_depth = Arc::clone(&sender.queued_depth);
            let terminal_drain_wakeup = Arc::clone(&sender.terminal_drain_wakeup);
            let cx = crate::cx::for_testing();
            let (mutation_tx, mutation_rx) = oneshot::channel();
            let (tail_tx, tail_rx) = oneshot::channel();
            let (shutdown_tx, shutdown_rx) = oneshot::channel();

            sender
                .send_with_cx(
                    &cx,
                    WriteCommand::MarkEventHandled {
                        event_id: 42,
                        workflow_id: None,
                        status: "handled".to_string(),
                        respond: mutation_tx,
                    },
                )
                .await
                .expect("queue raw mutation panic");
            sender
                .send_with_cx(&cx, WriteCommand::Vacuum { respond: tail_tx })
                .await
                .expect("queue later backend command");
            sender
                .send_with_cx(
                    &cx,
                    WriteCommand::Shutdown {
                        respond: shutdown_tx,
                    },
                )
                .await
                .expect("queue shutdown tail");

            let mut mmap_mirror = None;
            writer_loop(
                &backend,
                &mut rx,
                &mut mmap_mirror,
                queued_depth.as_ref(),
                terminal_drain_wakeup.as_ref(),
                terminal_state.as_ref(),
                terminal_admission_gate.as_ref(),
                false,
                None,
                true,
            );

            let mutation = crate::runtime_async::oneshot_recv(mutation_rx)
                .await
                .expect("panicking mutation response");
            assert!(matches!(
                mutation,
                Err(crate::Error::Storage(
                    StorageError::WriterBackendEpochPoisoned
                ))
            ));
            let tail = crate::runtime_async::oneshot_recv(tail_rx)
                .await
                .expect("undispatched backend tail response");
            assert!(matches!(
                tail,
                Err(crate::Error::Storage(
                    StorageError::WriterBackendEpochPoisoned
                ))
            ));
            crate::runtime_async::oneshot_recv(shutdown_rx)
                .await
                .expect("drained shutdown tail acknowledgment");

            assert_eq!(backend.mutation_count.load(AtomicOrdering::Relaxed), 1);
            assert_eq!(backend.calls(), vec!["raw_mutation_then_panic"]);
            assert_eq!(
                backend.post_panic_calls.load(AtomicOrdering::Relaxed),
                0,
                "no later raw command, adaptive observation, flush, or teardown callback may reuse the poisoned backend"
            );
            assert_eq!(queued_depth.load(AtomicOrdering::Acquire), 0);
            assert_eq!(
                terminal_state.load(AtomicOrdering::Acquire),
                WRITER_TERMINAL_BACKEND_EPOCH_POISONED
            );
        });
    }

    // ----------------------------------------------------------------------
    // [round-4 Q2] group-commit widen (events/gaps) + condvar wake proofs.
    //
    // Byte-equivalence strategy: the coalesced path calls the SAME per-command
    // backends (`record_event_backend` / `record_gap_backend`) the legacy raw
    // path calls, so the persisted statement stream — SQL, params, insert order,
    // and `RETURNING` ids — is identical; only the transaction (fsync) boundary
    // widens, which a DB dump cannot observe. These tests pin (a) one explicit
    // transaction around a multi-command run, (b) per-command result order, (c)
    // crash-atomicity (any failure rolls the whole group back and fails every
    // caller), (d) singleton == legacy raw path, and (e) a real-SQLite dump that
    // is identical with the gate on vs off.
    // ----------------------------------------------------------------------

    fn sample_event(
        pane_id: u64,
        rule_id: &str,
        detected_at: i64,
        dedupe_key: Option<&str>,
    ) -> StoredEvent {
        StoredEvent {
            id: 0,
            pane_id,
            rule_id: rule_id.to_string(),
            agent_type: "unknown".to_string(),
            event_type: "pattern".to_string(),
            severity: "info".to_string(),
            confidence: 0.9,
            extracted: None,
            matched_text: Some(format!("match-{rule_id}")),
            segment_id: None,
            detected_at,
            dedupe_key: dedupe_key.map(str::to_string),
            handled_at: None,
            handled_by_workflow_id: None,
            handled_status: None,
        }
    }

    #[test]
    fn event_gap_group_commit_uses_single_transaction_and_keeps_result_order() {
        run_storage_async_test(async {
            let backend = crate::storage_backend_trait::MockBackend::new();
            // One INSERT...RETURNING id per event, in dispatch order.
            backend.enqueue_row_response(Some(vec!["201".to_string()]));
            backend.enqueue_row_response(Some(vec!["202".to_string()]));
            backend.enqueue_row_response(Some(vec!["203".to_string()]));

            let (tx1, rx1) = oneshot::channel();
            let (tx2, rx2) = oneshot::channel();
            let (tx3, rx3) = oneshot::channel();
            let group = vec![
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(7, "r1", 1_700_000_000_000, Some("k1"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx1),
                },
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(7, "r2", 1_700_000_000_001, Some("k2"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx2),
                },
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(7, "r3", 1_700_000_000_002, Some("k3"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx3),
                },
            ];
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();

            let result = event_gap_group_commit_backend(
                &backend,
                &group,
                &mut mmap_mirror,
                &mut segment_redactors,
            )
            .expect("event group commit should succeed");
            dispatch_event_gap_group_commit_result(Ok(result), group);

            let outcome1 = crate::runtime_async::oneshot_recv(rx1)
                .await
                .expect("first response")
                .expect("first ok");
            let outcome2 = crate::runtime_async::oneshot_recv(rx2)
                .await
                .expect("second response")
                .expect("second ok");
            let outcome3 = crate::runtime_async::oneshot_recv(rx3)
                .await
                .expect("third response")
                .expect("third ok");
            assert_eq!(
                (
                    outcome1.event_id(),
                    outcome2.event_id(),
                    outcome3.event_id()
                ),
                (201, 202, 203),
                "ids in submission order"
            );
            assert!(
                outcome1.was_inserted() && outcome2.was_inserted() && outcome3.was_inserted(),
                "mocked INSERT RETURNING rows are newly inserted events"
            );

            assert_eq!(
                backend.executed(),
                vec!["BEGIN".to_string(), "COMMIT".to_string()],
                "grouped events must use exactly one explicit transaction"
            );
            let insert_count = backend
                .observed_queries()
                .iter()
                .filter(|(sql, _)| sql.contains("INSERT INTO events"))
                .count();
            assert_eq!(
                insert_count, 3,
                "every grouped event inserts inside the txn"
            );
        });
    }

    #[test]
    fn event_gap_group_commit_reports_in_batch_dedupe_without_a_second_insertion() {
        run_storage_async_test(async {
            let backend = crate::storage_backend_trait::MockBackend::new();
            backend.enqueue_row_response(Some(vec!["211".to_string()]));
            backend.enqueue_row_response(None);
            backend.enqueue_row_response(Some(vec!["211".to_string()]));

            let (first_tx, first_rx) = oneshot::channel();
            let (retry_tx, retry_rx) = oneshot::channel();
            let group = vec![
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(
                        7,
                        "same-rule",
                        1_700_000_000_000,
                        Some("same-key"),
                    )),
                    capture_hold: None,
                    respond: WriterResultResponder::new(first_tx),
                },
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(
                        7,
                        "same-rule",
                        1_700_000_000_001,
                        Some("same-key"),
                    )),
                    capture_hold: None,
                    respond: WriterResultResponder::new(retry_tx),
                },
            ];
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();

            let result = event_gap_group_commit_backend(
                &backend,
                &group,
                &mut mmap_mirror,
                &mut segment_redactors,
            )
            .expect("deduplicated event group should commit");
            dispatch_event_gap_group_commit_result(Ok(result), group);

            let first = crate::runtime_async::oneshot_recv(first_rx)
                .await
                .expect("first response")
                .expect("first insert");
            let retry = crate::runtime_async::oneshot_recv(retry_rx)
                .await
                .expect("retry response")
                .expect("dedupe lookup");
            assert_eq!(first.inserted_event_id(), Some(211));
            assert_eq!(retry.inserted_event_id(), None);
            assert_eq!(retry.event_id(), first.event_id());

            let queries = backend.observed_queries();
            assert_eq!(queries.len(), 3);
            assert!(queries[0].0.contains("INSERT INTO events"));
            assert!(queries[1].0.contains("INSERT INTO events"));
            assert!(queries[2].0.contains("SELECT id FROM events"));
            assert_eq!(
                backend.executed(),
                vec!["BEGIN".to_string(), "COMMIT".to_string()]
            );
        });
    }

    #[test]
    fn event_gap_group_commit_mixes_events_and_gaps_in_one_transaction() {
        run_storage_async_test(async {
            let backend = crate::storage_backend_trait::MockBackend::new();
            backend.enqueue_row_response(Some(vec!["301".to_string()])); // event 1 id
            backend.enqueue_row_response(Some(vec!["5".to_string()])); // gap MAX(seq)
            backend.enqueue_row_response(Some(vec!["77".to_string()])); // gap id
            backend.enqueue_row_response(Some(vec!["302".to_string()])); // event 2 id

            let (tx1, rx1) = oneshot::channel();
            let (gtx, grx) = oneshot::channel();
            let (tx2, rx2) = oneshot::channel();
            let group = vec![
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(7, "r1", 1_700_000_000_000, Some("k1"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx1),
                },
                PendingEventOrGap::Gap {
                    pane_id: 7,
                    reason: "capture gap".to_string(),
                    capture_hold: None,
                    respond: WriterResultResponder::new(gtx),
                },
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(7, "r2", 1_700_000_000_002, Some("k2"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx2),
                },
            ];
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();

            let result = event_gap_group_commit_backend(
                &backend,
                &group,
                &mut mmap_mirror,
                &mut segment_redactors,
            )
            .expect("mixed group commit should succeed");
            dispatch_event_gap_group_commit_result(Ok(result), group);

            let outcome1 = crate::runtime_async::oneshot_recv(rx1)
                .await
                .expect("event1")
                .expect("event1 ok");
            let gap = crate::runtime_async::oneshot_recv(grx)
                .await
                .expect("gap")
                .expect("gap ok")
                .expect("gap recorded");
            let outcome2 = crate::runtime_async::oneshot_recv(rx2)
                .await
                .expect("event2")
                .expect("event2 ok");

            assert_eq!(outcome1.inserted_event_id(), Some(301));
            assert_eq!(outcome2.inserted_event_id(), Some(302));
            assert_eq!(gap.id, 77);
            assert_eq!(gap.seq_before, 5);
            assert_eq!(gap.seq_after, 6);
            assert_eq!(gap.reason, "capture gap");

            assert_eq!(
                backend.executed(),
                vec!["BEGIN".to_string(), "COMMIT".to_string()],
                "interleaved events+gaps share one transaction"
            );
        });
    }

    #[test]
    fn event_gap_group_commit_mid_group_failure_rolls_back_and_fails_all() {
        run_storage_async_test(async {
            let backend = crate::storage_backend_trait::MockBackend::new();
            backend.enqueue_row_response(Some(vec!["401".to_string()])); // event 1 ok
            backend.enqueue_row_response(None); // event 2 -> no id -> Err

            let (tx1, rx1) = oneshot::channel();
            let (tx2, rx2) = oneshot::channel();
            let group = vec![
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(9, "r1", 1_700_000_000_000, Some("k1"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx1),
                },
                PendingEventOrGap::Event {
                    event: Box::new(sample_event(9, "r2", 1_700_000_000_001, Some("k2"))),
                    capture_hold: None,
                    respond: WriterResultResponder::new(tx2),
                },
            ];
            let mut mmap_mirror = None;
            let mut segment_redactors = HashMap::<u64, SegmentPersistRedactor>::new();

            let result = event_gap_group_commit_backend(
                &backend,
                &group,
                &mut mmap_mirror,
                &mut segment_redactors,
            );
            assert!(result.is_err(), "a failed insert must abort the group");
            assert_eq!(
                backend.executed(),
                vec!["BEGIN".to_string(), "ROLLBACK".to_string()],
                "a mid-group failure must roll the whole transaction back"
            );
            dispatch_event_gap_group_commit_result(result, group);

            // The first event "succeeded" in-transaction but the rollback undid
            // it, so its caller is told the write failed — never a false Ok.
            let first = crate::runtime_async::oneshot_recv(rx1).await.expect("rx1");
            assert!(first.is_err(), "first grouped caller fails closed");
            let second = crate::runtime_async::oneshot_recv(rx2).await.expect("rx2");
            assert!(second.is_err(), "second grouped caller fails closed");
        });
    }

    #[test]
    fn event_gap_group_ordinary_rollback_restores_gap_redactor_snapshot() {
        let _ = take_writer_backend_epoch_poisoned_signal();
        let backend = crate::storage_backend_trait::MockBackend::new();
        backend.enqueue_row_response(Some(vec!["5".to_string()]));
        backend.enqueue_row_response(Some(vec!["77".to_string()]));
        backend.enqueue_row_response(None);

        let (gap_tx, _gap_rx) = oneshot::channel();
        let (event_tx, _event_rx) = oneshot::channel();
        let group = vec![
            PendingEventOrGap::Gap {
                pane_id: 7,
                reason: "capture gap before later failure".to_string(),
                capture_hold: None,
                respond: WriterResultResponder::new(gap_tx),
            },
            PendingEventOrGap::Event {
                event: Box::new(sample_event(
                    7,
                    "later-failing-event",
                    1_700_000_000_001,
                    Some("later-failing-dedupe"),
                )),
                capture_hold: None,
                respond: WriterResultResponder::new(event_tx),
            },
        ];
        let mut mmap_mirror = None;
        let expected_redactor = SegmentPersistRedactor {
            lookback: "pre-gap raw lookback sk-".to_string(),
        };
        let mut segment_redactors = HashMap::from([(7, expected_redactor.clone())]);

        let result = event_gap_group_commit_backend(
            &backend,
            &group,
            &mut mmap_mirror,
            &mut segment_redactors,
        );

        assert!(
            result.is_err(),
            "the later event mutation must fail the group"
        );
        assert_eq!(
            backend.executed(),
            vec!["BEGIN".to_string(), "ROLLBACK".to_string()],
            "the gap SQL and later mutation share one proven ordinary rollback"
        );
        assert_eq!(
            segment_redactors.get(&7),
            Some(&expected_redactor),
            "an ordinary group rollback must restore the exact pre-gap lookback"
        );
        assert!(!take_writer_backend_epoch_poisoned_signal());
    }

    struct CommitFailBackend {
        inner: crate::storage_backend_trait::MockBackend,
    }

    impl CommitFailBackend {
        fn new() -> Self {
            Self {
                inner: crate::storage_backend_trait::MockBackend::new(),
            }
        }

        fn executed(&self) -> Vec<String> {
            self.inner.executed()
        }
    }

    impl StorageBackend for CommitFailBackend {
        fn execute(&self, sql: &str) -> std::result::Result<usize, BackendError> {
            if sql.trim().eq_ignore_ascii_case("COMMIT") {
                return Err(BackendError::Query("injected commit failure".to_string()));
            }
            self.inner.execute(sql)
        }

        fn execute_batch(&self, sql: &str) -> std::result::Result<(), BackendError> {
            self.inner.execute_batch(sql)
        }

        fn set_busy_timeout(
            &self,
            timeout: std::time::Duration,
        ) -> std::result::Result<(), BackendError> {
            self.inner.set_busy_timeout(timeout)
        }

        fn query_scalar(&self, sql: &str) -> std::result::Result<Option<String>, BackendError> {
            self.inner.query_scalar(sql)
        }

        fn transaction_state(&self) -> std::result::Result<BackendTransactionState, BackendError> {
            self.inner.transaction_state()
        }

        fn begin_transaction(
            &self,
        ) -> std::result::Result<crate::storage_backend_trait::TransactionGuard<'_>, BackendError>
        {
            self.inner.begin_transaction()
        }

        fn user_version(&self) -> std::result::Result<u32, BackendError> {
            self.inner.user_version()
        }

        fn set_user_version(&self, version: u32) -> std::result::Result<(), BackendError> {
            self.inner.set_user_version(version)
        }

        fn backend_name(&self) -> &'static str {
            "commit_fail"
        }

        fn query_row_strings(
            &self,
            sql: &str,
            params: &[&str],
        ) -> std::result::Result<Option<Vec<String>>, BackendError> {
            self.inner.query_row_strings(sql, params)
        }

        fn query_map_strings(
            &self,
            sql: &str,
            params: &[&str],
        ) -> std::result::Result<Vec<Vec<String>>, BackendError> {
            self.inner.query_map_strings(sql, params)
        }

        fn execute_many(
            &self,
            sql: &str,
            param_rows: &[Vec<ToSqlValue<'_>>],
        ) -> std::result::Result<usize, BackendError> {
            self.inner.execute_many(sql, param_rows)
        }
    }

