/// Per-pane state for append-time secret redaction at rest (ft-e8hd7).
///
/// Replaces the prior per-pane `StreamingRedactor`, which withheld a rolling
/// anchor-prefix *tail* from every persisted segment so a credential split
/// across two appends could still be caught. That withholding truncated the
/// live edge of each segment and pushed boundary bytes into the *next* segment,
/// so per-segment `search`/`get-text`/`export`/`dom` saw short or
/// boundary-split content (the `mcp_conformance_wa_search` + export-suite
/// regressions diagnosed under ft-00gvk).
///
/// Instead we persist the fully-redacted content of every segment *immediately*
/// (no withholding) and keep only a bounded **raw lookback** of the most recent
/// appended bytes. The lookback is used solely to detect a secret that
/// straddles an append boundary; when one is found its head is masked in the
/// current segment and its raw prior-segment bytes are stripped from however
/// many prior segments it spans (multi-segment retroactive masking). The
/// lookback holds *raw* (un-redacted) bytes so a credential whose body is split
/// mid-token is re-detected in full, preserving the prior design's cross-append
/// coverage.
#[derive(Debug, Default, Clone, PartialEq, Eq)]
struct SegmentPersistRedactor {
    /// Trailing *raw* bytes of the appended stream, capped at
    /// [`SEGMENT_REDACTION_LOOKBACK_BYTES`]. In-memory only; never persisted.
    lookback: String,
}

#[cfg(test)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AppendCommitFaultForTest {
    SingletonAfterRedaction,
    GroupAfterRedaction(usize),
}

#[cfg(test)]
thread_local! {
    /// One-shot append-transaction fault seam. The fault fires only after the
    /// redactor has advanced its lookback and had an opportunity to rewrite a
    /// prior row, so rollback tests exercise both durable and in-memory state.
    static APPEND_COMMIT_FAULT_FOR_TEST: std::cell::Cell<Option<AppendCommitFaultForTest>> =
        const { std::cell::Cell::new(None) };
}

#[cfg(test)]
fn set_append_commit_fault_for_test(fault: AppendCommitFaultForTest) {
    APPEND_COMMIT_FAULT_FOR_TEST.with(|slot| slot.set(Some(fault)));
}

#[cfg(test)]
fn maybe_fail_singleton_append_after_redaction_for_test() -> Result<()> {
    APPEND_COMMIT_FAULT_FOR_TEST.with(|slot| match slot.take() {
        Some(AppendCommitFaultForTest::SingletonAfterRedaction) => Err(StorageError::Database(
            "injected singleton append failure after redaction".to_string(),
        )
        .into()),
        other => {
            slot.set(other);
            Ok(())
        }
    })
}

#[cfg(not(test))]
fn maybe_fail_singleton_append_after_redaction_for_test() -> Result<()> {
    Ok(())
}

#[cfg(test)]
fn maybe_fail_group_append_after_redaction_for_test(write_index: usize) -> Result<()> {
    APPEND_COMMIT_FAULT_FOR_TEST.with(|slot| match slot.take() {
        Some(AppendCommitFaultForTest::GroupAfterRedaction(fault_index))
            if fault_index == write_index =>
        {
            Err(StorageError::Database(format!(
                "injected append group failure after redaction at write {write_index}"
            ))
            .into())
        }
        other => {
            slot.set(other);
            Ok(())
        }
    })
}

#[cfg(not(test))]
fn maybe_fail_group_append_after_redaction_for_test(_write_index: usize) -> Result<()> {
    Ok(())
}

/// Lookback window for cross-append secret detection at persist time
/// (ft-e8hd7). Matches the streaming redactor's retained-tail bound so a
/// credential split across appends is caught with the same span budget the
/// prior held-tail design used.
const SEGMENT_REDACTION_LOOKBACK_BYTES: usize = DEFAULT_STREAMING_REDACTOR_TAIL_BYTES;

/// Smallest char-boundary index `>= index` in `text` (clamped to `text.len()`).
/// Dropping *more* than requested is always safe for the lookback window.
fn next_char_boundary(text: &str, mut index: usize) -> usize {
    while index < text.len() && !text.is_char_boundary(index) {
        index += 1;
    }
    index
}

// Per-thread scan-byte accounting for `redact_segment_for_persistence`.
//
// The ft-gkh4p perf-regression tests use these to assert that the
// straddle-detection scan never re-reads the chunk past the span budget (the
// redundant second full scan that motivated the bead). Compiled out — and
// reduced to inlined no-ops at the call sites — in non-test builds.
#[cfg(test)]
thread_local! {
    static SEGMENT_REDACT_DETECT_BYTES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
    static SEGMENT_REDACT_REDACT_BYTES: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
fn record_segment_detect_scan(len: usize) {
    SEGMENT_REDACT_DETECT_BYTES.with(|cell| cell.set(cell.get() + len));
}

#[cfg(not(test))]
#[inline(always)]
fn record_segment_detect_scan(_len: usize) {}

#[cfg(test)]
fn record_segment_redact_scan(len: usize) {
    SEGMENT_REDACT_REDACT_BYTES.with(|cell| cell.set(cell.get() + len));
}

#[cfg(not(test))]
#[inline(always)]
fn record_segment_redact_scan(_len: usize) {}

#[cfg(test)]
fn reset_segment_scan_accounting() {
    SEGMENT_REDACT_DETECT_BYTES.with(|cell| cell.set(0));
    SEGMENT_REDACT_REDACT_BYTES.with(|cell| cell.set(0));
}

/// Returns `(detect_scan_bytes, redact_scan_bytes)` accumulated since the last
/// [`reset_segment_scan_accounting`] on this thread.
#[cfg(test)]
fn segment_scan_accounting() -> (usize, usize) {
    (
        SEGMENT_REDACT_DETECT_BYTES.with(std::cell::Cell::get),
        SEGMENT_REDACT_REDACT_BYTES.with(std::cell::Cell::get),
    )
}

/// Redact a segment for at-rest persistence, returning the redacted content and
/// whether a prior segment was retroactively edited (which invalidates the mmap
/// mirror). See [`SegmentPersistRedactor`] for the design.
///
/// Security invariant: a secret is never *complete* in persisted storage. A
/// secret fully inside `content` is redacted by [`Redactor::redact`]; a secret
/// straddling the prior↔current append boundary has its completing bytes (the
/// portion living in `content`) masked here, so even if the retroactive strip
/// of the prior raw prefix is skipped (lookback drift / pruning) no usable
/// credential survives.
fn redact_segment_for_persistence(
    backend: &dyn StorageBackend,
    pane_id: u64,
    content: &str,
    segment_redactors: &mut HashMap<u64, SegmentPersistRedactor>,
) -> Result<(String, bool)> {
    let redactor = Redactor::new();
    let state = segment_redactors.entry(pane_id).or_default();
    let boundary = state.lookback.len();

    // Fast path: an empty lookback means there is no append boundary, so no
    // secret can straddle one. Redact the chunk directly (the only scan it ever
    // needs) and seed the next lookback from its tail — no `lookback ++ content`
    // copy is materialized. This is the first append of a pane and the first
    // append after every gap/shutdown flush (ft-gkh4p).
    if boundary == 0 {
        record_segment_redact_scan(content.len());
        let persisted = redactor.redact(content);
        let keep_from = if content.len() > SEGMENT_REDACTION_LOOKBACK_BYTES {
            next_char_boundary(content, content.len() - SEGMENT_REDACTION_LOOKBACK_BYTES)
        } else {
            0
        };
        state.lookback = content[keep_from..].to_string();
        return Ok((persisted, false));
    }

    // Straddle detection only needs the *boundary region*, not the whole chunk.
    // A credential split across the append boundary is, by design, only caught
    // within the span budget `SEGMENT_REDACTION_LOOKBACK_BYTES` (it matches the
    // streaming redactor's retained-tail bound — see the field doc). A straddle
    // within that budget spans the boundary, so it has at least one byte in the
    // lookback and therefore fewer than `SEGMENT_REDACTION_LOOKBACK_BYTES` bytes
    // in `content`; capping the forward scan at the budget catches every such
    // straddle (the backward half is the full lookback, itself ≤ the budget) yet
    // never re-scans `content` past the point `redact(content)` already covers.
    // Before this cap, `detect(&combined)` regex-scanned the entire chunk a
    // second time on the hottest write path (ft-gkh4p). The window is a *prefix*
    // of the raw `lookback ++ content` stream, so detection offsets map onto it
    // and the full chunk directly.
    let fwd = if content.len() > SEGMENT_REDACTION_LOOKBACK_BYTES {
        next_char_boundary(content, SEGMENT_REDACTION_LOOKBACK_BYTES)
    } else {
        content.len()
    };
    let mut window = String::with_capacity(boundary + fwd);
    window.push_str(&state.lookback);
    window.push_str(&content[..fwd]);

    let persisted;
    let mut edited_prior = false;
    // At most one detected secret can contain the single boundary point, so the
    // first crossing span is the only straddle.
    record_segment_detect_scan(window.len());
    let straddle = redactor
        .detect(&window)
        .into_iter()
        .find(|&(_, start, end)| start < boundary && boundary < end);

    if let Some((_, start, end)) = straddle {
        // Bytes of the straddling secret that live in `content`
        // (`window[boundary..] == content[..fwd]`, and `end` is char-aligned).
        let head_len = end - boundary;
        // One canonical marker for the whole straddled secret, then the
        // remainder of the segment redacted normally.
        record_segment_redact_scan((end - start) + (content.len() - head_len));
        let marker = redactor.redact(&window[start..end]);
        persisted = format!("{marker}{}", redactor.redact(&content[head_len..]));
        // Strip the secret's raw prior-segment bytes from already-persisted
        // segments. They are an incomplete prefix that only completes with
        // `content`, so removing them loses no non-secret content.
        edited_prior = mask_split_secret_in_prior_segments_backend(
            backend,
            pane_id,
            &window[start..boundary],
        )?;
    } else {
        record_segment_redact_scan(content.len());
        persisted = redactor.redact(content);
    }

    // Advance the raw lookback to the last `SEGMENT_REDACTION_LOOKBACK_BYTES` of
    // the full `lookback ++ content` stream, derived from slices so the chunk
    // tail beyond the (possibly capped) detect window is still retained verbatim.
    if content.len() >= SEGMENT_REDACTION_LOOKBACK_BYTES {
        // The retained tail lies wholly inside `content`; the prior lookback
        // ages out entirely. `window` (the detect prefix) is dropped here.
        let keep_from =
            next_char_boundary(content, content.len() - SEGMENT_REDACTION_LOOKBACK_BYTES);
        state.lookback = content[keep_from..].to_string();
    } else {
        // `content` is shorter than the budget, so `fwd == content.len()` and
        // `window` is the *entire* `lookback ++ content` stream. Trim its head
        // in place and move the buffer into the lookback — no second allocation.
        debug_assert_eq!(fwd, content.len());
        let total = boundary + content.len();
        let keep_from = if total > SEGMENT_REDACTION_LOOKBACK_BYTES {
            next_char_boundary(&window, total - SEGMENT_REDACTION_LOOKBACK_BYTES)
        } else {
            0
        };
        if keep_from > 0 {
            window.drain(..keep_from);
        }
        state.lookback = window;
    }

    Ok((persisted, edited_prior))
}

/// Drop the per-pane cross-append lookback (ft-e8hd7). A gap or shutdown is a
/// stream discontinuity, so any retained lookback must not be combined with the
/// next chunk (that would manufacture a false straddle). Nothing is withheld
/// from persistence anymore, so there is no tail to flush as a new segment.
fn flush_segment_redactor_for_pane(
    _backend: &dyn StorageBackend,
    _mmap_mirror: &mut Option<mmap_store::MmapScrollbackStore>,
    segment_redactors: &mut HashMap<u64, SegmentPersistRedactor>,
    pane_id: u64,
) -> Result<()> {
    segment_redactors.remove(&pane_id);
    Ok(())
}

/// Strip the trailing `suffix` bytes from the persisted segment stream for
/// `pane_id`, walking newest→oldest across as many segments as the suffix spans
/// (ft-e8hd7). `suffix` is the raw prior-segment portion of a secret that
/// straddles an append boundary — an incomplete prefix that only completes with
/// the current chunk, so removing it loses no non-secret content. Returns
/// whether any prior segment was edited.
///
/// Defense-in-depth only: if the walk stops early because the persisted bytes
/// no longer match (the prior portion was itself a complete secret and got
/// redacted, or retention pruned the row), the straddling secret is still never
/// *complete* in storage — its completing bytes were masked in the current
/// segment by the caller.
fn mask_split_secret_in_prior_segments_backend(
    backend: &dyn StorageBackend,
    pane_id: u64,
    suffix: &str,
) -> Result<bool> {
    if suffix.is_empty() {
        return Ok(false);
    }

    let pane_id_i64 = u64_to_i64(pane_id, "pane_id")?;
    let mut remaining = suffix;
    let mut edited_any = false;
    // `id` cursor walks strictly older segments without re-reading rows we have
    // already emptied (per-pane `seq` and `id` are both monotonic with append).
    let mut cursor: Option<i64> = None;

    while !remaining.is_empty() {
        let row = match cursor {
            None => backend.query_row_typed(
                "SELECT id, content
                 FROM output_segments
                 WHERE pane_id = ?1
                 ORDER BY seq DESC, id DESC
                 LIMIT 1",
                &[ToSqlValue::Integer(pane_id_i64)],
            ),
            Some(prev_id) => backend.query_row_typed(
                "SELECT id, content
                 FROM output_segments
                 WHERE pane_id = ?1 AND id < ?2
                 ORDER BY seq DESC, id DESC
                 LIMIT 1",
                &[
                    ToSqlValue::Integer(pane_id_i64),
                    ToSqlValue::Integer(prev_id),
                ],
            ),
        }
        .map_err(|err| storage_backend_error("Failed to query prior segment", err))?;

        let Some(row) = row else { break };
        let reader = RowReader::new(&row);
        let segment_id = reader
            .i64(0)
            .map_err(|err| storage_backend_error("Failed to parse prior segment id", err))?;
        let content = reader
            .string(1)
            .map_err(|err| storage_backend_error("Failed to parse prior segment content", err))?;
        cursor = Some(segment_id);

        let new_content = if content.len() >= remaining.len() {
            // The straddle tail ends inside this segment.
            let Some(kept) = content.strip_suffix(remaining) else {
                break;
            };
            remaining = "";
            kept.to_string()
        } else {
            // This whole segment is part of the straddle tail; empty it and
            // continue stripping the rest from older segments.
            if !remaining.ends_with(content.as_str()) {
                break;
            }
            remaining = &remaining[..remaining.len() - content.len()];
            String::new()
        };

        let content_len_i64 = usize_to_i64(new_content.len(), "content_len")?;
        execute_typed(
            backend,
            "UPDATE output_segments
             SET content = ?1, content_len = ?2, content_hash = NULL
             WHERE id = ?3",
            &[
                ToSqlValue::Text(&new_content),
                ToSqlValue::Integer(content_len_i64),
                ToSqlValue::Integer(segment_id),
            ],
        )
        .map_err(|err| storage_backend_error("Failed to strip split secret tail", err))?;
        edited_any = true;
    }

    Ok(edited_any)
}

fn disable_mmap_mirror_after_retained_tail_move(
    mmap_mirror: &mut Option<mmap_store::MmapScrollbackStore>,
    pane_id: u64,
) {
    if mmap_mirror.is_some() {
        tracing::warn!(
            pane_id,
            "disabled mmap segment mirror after retained redaction tail updated a prior segment"
        );
        *mmap_mirror = None;
    }
}

/// Drop all per-pane cross-append lookback state (ft-e8hd7). Nothing is
/// withheld from persistence, so shutdown/teardown only needs to release the
/// in-memory lookback windows.
fn flush_segment_redactors(
    _backend: &dyn StorageBackend,
    _mmap_mirror: &mut Option<mmap_store::MmapScrollbackStore>,
    segment_redactors: &mut HashMap<u64, SegmentPersistRedactor>,
) {
    segment_redactors.clear();
}

// =============================================================================
// Synchronous Database Operations
// =============================================================================

/// Get current timestamp in epoch milliseconds
pub fn now_ms() -> i64 {
    crate::clock_anomaly::epoch_ms_i64("ft.storage.clock")
}

/// Get the current timestamp in epoch milliseconds, failing when the system
/// clock is unavailable (reports a pre-Unix-epoch time) instead of degrading
/// to [`now_ms`]'s `0` sentinel.
///
/// Security-sensitive expiry comparisons MUST use this variant: with the `0`
/// fallback, `expires_at >= 0` matches every token ever issued, so a broken
/// clock silently fails OPEN at the approval gate (and stamps `used_at = 0`
/// into the consumed row). Refusing the operation keeps those gates
/// fail-closed, matching the project-wide missing-telemetry doctrine.
fn now_ms_strict() -> Result<i64> {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .ok()
        .and_then(|d| i64::try_from(d.as_millis()).ok())
        .ok_or_else(|| {
            StorageError::Database(
                "system clock unavailable (reports a pre-Unix-epoch time); \
                 refusing to evaluate expiry"
                    .to_string(),
            )
            .into()
        })
}

fn checked_event_delivery_lease_ttl_ms(lease_ttl: std::time::Duration) -> Result<i64> {
    if lease_ttl.is_zero() {
        return Err(StorageError::Database(
            "event delivery lease TTL must be non-zero".to_string(),
        )
        .into());
    }

    // Persisted deadlines use epoch milliseconds. Round every positive
    // sub-millisecond remainder UP so storage never makes a lease stealable
    // before the caller's requested Duration has elapsed.
    const NANOS_PER_MILLI: u128 = 1_000_000;
    let ttl_nanos = lease_ttl.as_nanos();
    let ttl_ms_u128 = ttl_nanos.div_ceil(NANOS_PER_MILLI);
    let ttl_ms = i64::try_from(ttl_ms_u128).map_err(|_| {
        StorageError::Database(format!(
            "event delivery lease TTL exceeds the epoch-millisecond range: {lease_ttl:?}"
        ))
    })?;
    Ok(ttl_ms)
}

fn checked_event_delivery_lease_expiry(acquired_at_ms: i64, ttl_ms: i64) -> Result<i64> {
    if acquired_at_ms < 0 || ttl_ms <= 0 {
        return Err(StorageError::Database(format!(
            "invalid event delivery lease clock inputs: acquired_at_ms={acquired_at_ms}, ttl_ms={ttl_ms}"
        ))
        .into());
    }
    acquired_at_ms.checked_add(ttl_ms).ok_or_else(|| {
        StorageError::Database(format!(
            "event delivery lease expiry overflows epoch milliseconds: now={acquired_at_ms}, ttl_ms={ttl_ms}"
        ))
        .into()
    })
}

fn new_event_delivery_lease_token() -> String {
    let high: u128 = rand::random();
    let low: u128 = rand::random();
    format!("event-delivery-{high:032x}{low:032x}")
}

fn u64_to_i64(value: u64, label: &str) -> Result<i64> {
    i64::try_from(value).map_err(|_| {
        StorageError::Database(format!("{label} value {value} exceeds i64 range")).into()
    })
}

fn usize_to_i64(value: usize, label: &str) -> Result<i64> {
    i64::try_from(value).map_err(|_| {
        StorageError::Database(format!("{label} value {value} exceeds i64 range")).into()
    })
}

#[cfg(test)]
fn i64_to_u64_sql(value: i64, column_index: usize, label: &str) -> rusqlite::Result<u64> {
    u64::try_from(value).map_err(|_| {
        rusqlite::Error::FromSqlConversionFailure(
            column_index,
            rusqlite::types::Type::Integer,
            Box::new(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!("{label} value {value} is out of u64 range"),
            )),
        )
    })
}

fn i64_to_usize(value: i64) -> rusqlite::Result<usize> {
    usize::try_from(value).map_err(|_| rusqlite::Error::IntegralValueOutOfRange(0, value))
}

fn approval_token_from_backend_row(row: &[String]) -> Result<ApprovalTokenRecord> {
    let reader = RowReader::new(row);
    let pane_id = reader
        .optional_i64(7)
        .map_err(|err| storage_backend_error("Approval token pane_id", err))?
        .map(|value| backend_i64_to_u64(value, "approval_tokens.pane_id"))
        .transpose()
        .map_err(|err| storage_backend_error("Approval token pane_id", err))?;

    Ok(ApprovalTokenRecord {
        id: reader
            .i64(0)
            .map_err(|err| storage_backend_error("Approval token id", err))?,
        code_hash: reader
            .string(1)
            .map_err(|err| storage_backend_error("Approval token code_hash", err))?,
        created_at: reader
            .i64(2)
            .map_err(|err| storage_backend_error("Approval token created_at", err))?,
        expires_at: reader
            .i64(3)
            .map_err(|err| storage_backend_error("Approval token expires_at", err))?,
        used_at: reader
            .optional_i64(4)
            .map_err(|err| storage_backend_error("Approval token used_at", err))?,
        workspace_id: reader
            .string(5)
            .map_err(|err| storage_backend_error("Approval token workspace_id", err))?,
        action_kind: reader
            .string(6)
            .map_err(|err| storage_backend_error("Approval token action_kind", err))?,
        pane_id,
        action_fingerprint: reader
            .string(8)
            .map_err(|err| storage_backend_error("Approval token action_fingerprint", err))?,
        plan_hash: reader
            .optional_string(9)
            .map_err(|err| storage_backend_error("Approval token plan_hash", err))?,
        plan_version: reader
            .optional_i64(10)
            .map_err(|err| storage_backend_error("Approval token plan_version", err))?
            .map(|value| backend_i64_to_i32(value, "approval_tokens.plan_version"))
            .transpose()
            .map_err(|err| storage_backend_error("Approval token plan_version", err))?,
        risk_summary: reader
            .optional_string(11)
            .map_err(|err| storage_backend_error("Approval token risk_summary", err))?,
    })
}

fn prepared_plan_from_backend_row(row: &[String]) -> Result<PreparedPlanRecord> {
    let reader = RowReader::new(row);
    let pane_id = reader
        .optional_i64(4)
        .map_err(|err| storage_backend_error("Prepared plan pane_id", err))?
        .map(|value| backend_i64_to_u64(value, "prepared_plans.pane_id"))
        .transpose()
        .map_err(|err| storage_backend_error("Prepared plan pane_id", err))?;
    let requires_raw = reader
        .i64(8)
        .map_err(|err| storage_backend_error("Prepared plan requires_approval", err))?;
    let requires_approval =
        backend_i64_to_bool(requires_raw, "prepared_plans.requires_approval")
            .map_err(|err| storage_backend_error("Prepared plan requires_approval", err))?;

    Ok(PreparedPlanRecord {
        plan_id: reader
            .string(0)
            .map_err(|err| storage_backend_error("Prepared plan plan_id", err))?,
        plan_hash: reader
            .string(1)
            .map_err(|err| storage_backend_error("Prepared plan plan_hash", err))?,
        workspace_id: reader
            .string(2)
            .map_err(|err| storage_backend_error("Prepared plan workspace_id", err))?,
        action_kind: reader
            .string(3)
            .map_err(|err| storage_backend_error("Prepared plan action_kind", err))?,
        pane_id,
        pane_uuid: reader
            .optional_string(5)
            .map_err(|err| storage_backend_error("Prepared plan pane_uuid", err))?,
        params_json: reader
            .optional_string(6)
            .map_err(|err| storage_backend_error("Prepared plan params_json", err))?,
        plan_json: reader
            .string(7)
            .map_err(|err| storage_backend_error("Prepared plan plan_json", err))?,
        requires_approval,
        created_at: reader
            .i64(9)
            .map_err(|err| storage_backend_error("Prepared plan created_at", err))?,
        expires_at: reader
            .i64(10)
            .map_err(|err| storage_backend_error("Prepared plan expires_at", err))?,
        consumed_at: reader
            .optional_i64(11)
            .map_err(|err| storage_backend_error("Prepared plan consumed_at", err))?,
    })
}

fn query_approval_token_by_code_backend(
    backend: &dyn StorageBackend,
    code_hash: &str,
    workspace_id: &str,
) -> Result<Option<ApprovalTokenRecord>> {
    let row = backend
        .query_row_typed(
            "SELECT id, code_hash, created_at, expires_at, used_at, workspace_id, action_kind,
                    pane_id, action_fingerprint, plan_hash, plan_version, risk_summary
             FROM approval_tokens
             WHERE code_hash = ?1
               AND workspace_id = ?2
             LIMIT 1",
            &[ToSqlValue::Text(code_hash), ToSqlValue::Text(workspace_id)],
        )
        .map_err(|err| storage_backend_error("Query approval token by code", err))?;

    row.as_deref()
        .map(approval_token_from_backend_row)
        .transpose()
}

fn query_approval_token_by_id_backend(
    backend: &dyn StorageBackend,
    token_id: i64,
    workspace_id: &str,
) -> Result<Option<ApprovalTokenRecord>> {
    let row = backend
        .query_row_typed(
            "SELECT id, code_hash, created_at, expires_at, used_at, workspace_id, action_kind,
                    pane_id, action_fingerprint, plan_hash, plan_version, risk_summary
             FROM approval_tokens
             WHERE id = ?1
               AND workspace_id = ?2
             LIMIT 1",
            &[
                ToSqlValue::Integer(token_id),
                ToSqlValue::Text(workspace_id),
            ],
        )
        .map_err(|err| storage_backend_error("Query approval token by id", err))?;

    row.as_deref()
        .map(approval_token_from_backend_row)
        .transpose()
}

fn query_approval_tokens_backend(
    backend: &dyn StorageBackend,
    workspace_id: &str,
    include_inactive: bool,
    limit: usize,
    now_ms: i64,
) -> Result<Vec<ApprovalTokenRecord>> {
    let limit = if limit == 0 { 1 } else { limit };
    let limit = i64::try_from(limit).unwrap_or(i64::MAX);
    let mut sql = String::from(
        "SELECT id, code_hash, created_at, expires_at, used_at, workspace_id, action_kind,
                pane_id, action_fingerprint, plan_hash, plan_version, risk_summary
         FROM approval_tokens
         WHERE workspace_id = ?1",
    );
    let mut params = vec![ToSqlValue::Text(workspace_id)];
    if !include_inactive {
        sql.push_str(" AND used_at IS NULL AND expires_at >= ?2");
        params.push(ToSqlValue::Integer(now_ms));
    }
    let limit_param = params.len() + 1;
    sql.push_str(&format!(" ORDER BY created_at ASC LIMIT ?{limit_param}"));
    params.push(ToSqlValue::Integer(limit));

    let rows = backend
        .query_map_typed(&sql, &params)
        .map_err(|err| storage_backend_error("List approval tokens", err))?;
    rows.iter()
        .map(|row| approval_token_from_backend_row(row))
        .collect()
}

fn query_active_approvals_count_backend(
    backend: &dyn StorageBackend,
    workspace_id: &str,
    now_ms: i64,
) -> Result<u32> {
    let row = backend
        .query_row_typed(
            "SELECT COUNT(*) FROM approval_tokens
             WHERE workspace_id = ?1 AND used_at IS NULL AND expires_at >= ?2",
            &[ToSqlValue::Text(workspace_id), ToSqlValue::Integer(now_ms)],
        )
        .map_err(|err| storage_backend_error("Count active approvals", err))?;

    let Some(row) = row else {
        return Ok(0);
    };
    let count = RowReader::new(&row)
        .i64(0)
        .map_err(|err| storage_backend_error("Active approval count", err))?;
    u32::try_from(count).map_err(|_| {
        StorageError::Database(format!("Active approval count {count} exceeds u32 range")).into()
    })
}

