#[test]
fn writer_session_mutations_reject_a_partial_owner_tuple() {
    let mut conn = rusqlite::Connection::open_in_memory().expect("open corrupt-owner fixture");
    initialize_schema(&conn).expect("initialize corrupt-owner fixture");
    let topology =
        "{\"captured_at\":0,\"schema_version\":1,\"windows\":[],\"workspace_id\":null}";
    let owner = crate::session_retention::SessionOwnerIdentity {
        host_id: r#"{"version":5,"hostname":"test-host","machine_fence":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","boot_id":"11111111-1111-4111-8111-111111111111","process_domain_id":"test-domain"}"#.to_string(),
        pid: 4_101,
        process_start: 9_001,
    };
    let mux = PreparedMuxSession {
        topology_json: topology.to_string(),
    };
    with_test_storage_backend(&mut conn, |backend| {
        insert_mux_session_backend(
            backend,
            "partial-owner-writer-session",
            &mux,
            "test",
            None,
            Some(&owner),
        )
    })
    .expect("insert complete owner tuple");

    // Construct a legacy/corrupt partial tuple by suspending both layers that
    // now reject it. Reinstall the exact canonical mutation trigger before the
    // production writer path is exercised.
    conn.execute_batch(
        "PRAGMA ignore_check_constraints=ON;
         DROP TRIGGER mux_sessions_retained_size_au;
         UPDATE mux_sessions
         SET owner_heartbeat_at = NULL
         WHERE session_id = 'partial-owner-writer-session';
         PRAGMA ignore_check_constraints=OFF;",
    )
    .expect("construct partial owner tuple");
    conn.execute_batch(
        crate::storage::migrations::session_retained_size_schema_sql()
            .expect("canonical retained-size DDL must be extractable"),
    )
    .expect("restore canonical session update trigger");
    crate::storage::migrations::validate_session_retained_size_mutation_schema(&conn)
        .expect("restore exact retained-size mutation schema");

    let checkpoint = PreparedSessionCheckpoint {
        topology_json: topology.to_string(),
        metadata_json: None,
        panes: Vec::new(),
        pane_count: 0,
        total_bytes: 0,
    };
    let mutation = with_test_storage_backend(&mut conn, |backend| {
        insert_session_checkpoint_backend(
            backend,
            "partial-owner-writer-session",
            "periodic",
            &checkpoint,
            Some(&owner),
        )
    });
    assert!(
        mutation.is_err(),
        "writer must not heal or claim a corrupt partial owner tuple"
    );
    assert_eq!(
        conn.query_row("SELECT COUNT(*) FROM session_checkpoints", [], |row| {
            row.get::<_, i64>(0)
        })
        .expect("count checkpoints after rejected partial-owner mutation"),
        0
    );
}

/// ft-xbnl0.2.3 Cx-first: tick 143 mux-session/checkpoint cluster —
/// 8 storage cx-first siblings exercised end-to-end:
/// `insert_mux_session_with_cx`,
/// `insert_session_checkpoint_with_cx`,
/// `prune_session_checkpoints_with_cx`,
/// `mark_session_shutdown_clean_with_cx`,
/// `get_latest_checkpoint_hash_with_cx`,
/// `get_agent_session_with_cx`,
/// `get_active_sessions_with_cx`,
/// `get_sessions_for_pane_with_cx`.
#[test]
fn storage_tick143_mux_session_checkpoint_cluster_roundtrip() {
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!("wa_test_tick143_{}.db", std::process::id()));
        let db_path_str = db_path.to_string_lossy().to_string();
        let cx = crate::cx::for_testing();
        let storage = StorageHandle::new_with_cx(&cx, &db_path_str).await.unwrap();
        let empty_topology =
            "{\"captured_at\":0,\"schema_version\":1,\"windows\":[],\"workspace_id\":null}"
                .to_string();

        // 1. insert_mux_session_with_cx
        let session_id = "sess-tick143".to_string();
        storage
            .insert_mux_session_with_cx(
                &cx,
                session_id.clone(),
                empty_topology.clone(),
                "test-ft-version".to_string(),
                Some("host-tick143".to_string()),
            )
            .await
            .unwrap();

        // 2. insert_session_checkpoint_with_cx — three checkpoints so prune
        //    below has something to remove.
        let mut first_receipt = None;
        let mut latest_receipt = None;
        let mut latest_topology_json = None;
        for i in 0..3 {
            let pane_states = if i == 2 {
                vec![SessionPaneStateRow {
                    pane_id: 143,
                    cwd: Some("/tmp/tick143".to_string()),
                    command: Some("ft-test-shell".to_string()),
                    env_json: Some("{\"TERM\":\"xterm-256color\"}".to_string()),
                    terminal_state_json:
                        "{\"rows\":24,\"cols\":80,\"cursor_row\":0,\"cursor_col\":0,\"is_alt_screen\":false,\"title\":\"tick143\"}"
                            .to_string(),
                    agent_metadata_json: Some("{\"agent_type\":\"tick143\"}".to_string()),
                    scrollback_checkpoint_seq: Some(7),
                    last_output_at: Some(143_000),
                }]
            } else {
                Vec::new()
            };
            let topology_json = if pane_states.is_empty() {
                empty_topology.clone()
            } else {
                serde_json::json!({
                    "captured_at": 0,
                    "schema_version": 1,
                    "windows": [{
                        "active_tab_index": 0,
                        "position": null,
                        "size": null,
                        "tabs": [{
                            "active_pane_id": 143,
                            "pane_tree": {
                                "cols": 80,
                                "cwd": "/tmp/tick143",
                                "is_active": true,
                                "pane_id": 143,
                                "rows": 24,
                                "title": null,
                                "type": "Leaf"
                            },
                            "tab_id": 0,
                            "title": null
                        }],
                        "title": null,
                        "window_id": 0
                    }],
                    "workspace_id": null
                })
                .to_string()
            };
            if i == 2 {
                latest_topology_json = Some(
                    prepare_checkpoint_topology(&topology_json)
                        .expect("prepare expected latest topology")
                        .1,
                );
            }
            let metadata_json = (i == 0).then(|| "{\"source\":\"tick143\"}".to_string());
            let receipt = storage
                .insert_session_checkpoint_with_cx(
                    &cx,
                    session_id.clone(),
                    "periodic".to_string(),
                    topology_json,
                    metadata_json,
                    pane_states,
                )
                .await
                .unwrap();
            assert!(receipt.checkpoint_id() > 0);
            assert!(receipt.state_hash().starts_with("snp2:"));
            if first_receipt.is_none() {
                first_receipt = Some(receipt.clone());
            }
            latest_receipt = Some(receipt);
        }
        let first_receipt = first_receipt.expect("three checkpoints yield a first receipt");
        let latest_receipt = latest_receipt.expect("three checkpoints yield a latest receipt");
        let latest_topology_json =
            latest_topology_json.expect("latest checkpoint carries pane topology");
        let latest_checkpoint_id = latest_receipt.checkpoint_id();
        let latest_state_hash = latest_receipt.state_hash().to_string();

        let stale_close = storage
            .mark_session_shutdown_clean_with_cx(&cx, first_receipt)
            .await;
        assert!(
            stale_close.is_err(),
            "a superseded checkpoint must not authorize clean shutdown"
        );

        // 3. get_latest_checkpoint_hash_with_cx — should match the last one.
        let latest = storage
            .get_latest_checkpoint_hash_with_cx(&cx, session_id.clone())
            .await
            .unwrap();
        assert_eq!(latest.as_deref(), Some(latest_receipt.state_hash()));

        // 4. prune_session_checkpoints_with_cx — retain 1, should remove 2.
        let pruned = storage
            .prune_session_checkpoints_with_cx(&cx, session_id.clone(), 1)
            .await
            .unwrap();
        assert_eq!(
            pruned, 2,
            "retention=1 should prune the two older checkpoints"
        );

        // Latest should still be the exact same receipt after pruning.
        let after_prune = storage
            .get_latest_checkpoint_hash_with_cx(&cx, session_id.clone())
            .await
            .unwrap();
        assert_eq!(
            after_prune.as_deref(),
            Some(latest_receipt.state_hash())
        );

        // 5. mark_session_shutdown_clean_with_cx — exact latest receipt only.
        // A same-length, structurally valid pane-state mutation leaves the
        // declared byte count unchanged and therefore exercises the full
        // witness recomputation rather than only the structural preflight.
        let tamper_conn = rusqlite::Connection::open(&db_path).expect("open pane tamper fixture");
        let original_terminal_state: String = tamper_conn
            .query_row(
                "SELECT terminal_state_json
                 FROM mux_pane_state
                 WHERE checkpoint_id = ?1",
                [latest_checkpoint_id],
                |row| row.get(0),
            )
            .expect("read latest pane state before tamper");
        let tampered_terminal_state =
            original_terminal_state.replace("\"cursor_col\":0", "\"cursor_col\":1");
        assert_ne!(tampered_terminal_state, original_terminal_state);
        assert_eq!(tampered_terminal_state.len(), original_terminal_state.len());
        tamper_conn
            .execute(
                "UPDATE mux_pane_state
                 SET terminal_state_json = ?1
                 WHERE checkpoint_id = ?2",
                rusqlite::params![tampered_terminal_state, latest_checkpoint_id],
            )
            .expect("tamper latest pane state after checkpoint receipt");
        drop(tamper_conn);
        let tampered_close = storage
            .mark_session_shutdown_clean_with_cx(&cx, latest_receipt.clone())
            .await;
        assert!(
            tampered_close.is_err(),
            "pane-state mutation must invalidate an otherwise exact receipt"
        );
        let repair_conn = rusqlite::Connection::open(&db_path).expect("open pane repair fixture");
        repair_conn
            .execute(
                "UPDATE mux_pane_state
                 SET terminal_state_json = ?1
                 WHERE checkpoint_id = ?2",
                rusqlite::params![original_terminal_state, latest_checkpoint_id],
            )
            .expect("restore exact pane-state witness bytes");
        drop(repair_conn);
        storage
            .mark_session_shutdown_clean_with_cx(&cx, latest_receipt)
            .await
            .unwrap();

        // 6. AgentSession read cluster — seed one session so the backend
        //    cell decoder covers nullable text + optional float fields.
        storage
            .upsert_pane_with_cx(
                &cx,
                PaneRecord {
                    pane_id: 143,
                    pane_uuid: Some("pane-uuid-tick143".to_string()),
                    domain: "local".to_string(),
                    window_id: None,
                    tab_id: None,
                    title: Some("tick143-agent".to_string()),
                    cwd: Some("/tmp/tick143".to_string()),
                    tty_name: None,
                    first_seen_at: 143_000,
                    last_seen_at: 143_001,
                    observed: true,
                    ignore_reason: None,
                    last_decision_at: None,
                },
            )
            .await
            .unwrap();

        let mut agent_session = AgentSessionRecord::new_start(143, "codex");
        agent_session.session_id = Some("codex-session-tick143".to_string());
        agent_session.external_id = Some(String::new());
        agent_session.external_meta = Some(serde_json::json!({"source":"tick143"}));
        agent_session.model_name = Some("gpt-test".to_string());
        agent_session.total_tokens = Some(1430);
        agent_session.estimated_cost_usd = Some(0.125);
        let agent_session_id = storage
            .upsert_agent_session_with_cx(&cx, agent_session)
            .await
            .unwrap();

        let loaded = storage
            .get_agent_session_with_cx(&cx, agent_session_id)
            .await
            .unwrap()
            .expect("seeded agent session should load");
        assert_eq!(loaded.pane_id, 143);
        assert_eq!(loaded.session_id.as_deref(), Some("codex-session-tick143"));
        assert_eq!(loaded.external_id.as_deref(), Some(""));
        assert_eq!(loaded.total_tokens, Some(1430));
        assert_eq!(loaded.estimated_cost_usd, Some(0.125));

        // 7. get_active_sessions_with_cx.
        let active = storage.get_active_sessions_with_cx(&cx).await.unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0].id, agent_session_id);

        // 8. get_sessions_for_pane_with_cx.
        let pane_sessions = storage
            .get_sessions_for_pane_with_cx(&cx, 143)
            .await
            .unwrap();
        assert_eq!(pane_sessions.len(), 1);
        assert_eq!(pane_sessions[0].id, agent_session_id);

        storage.shutdown_with_cx(&cx).await.unwrap();
        let conn = rusqlite::Connection::open(&db_path).expect("open checkpoint evidence");
        let (role, witness, topology): (String, String, Option<String>) = conn
            .query_row(
                "SELECT checkpoint_role, state_hash, topology_json
                 FROM session_checkpoints WHERE id = ?1",
                [latest_checkpoint_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("load committed checkpoint evidence");
        assert_eq!(role, "snapshot");
        assert_eq!(witness, latest_state_hash);
        assert_eq!(topology.as_deref(), Some(latest_topology_json.as_str()));
        let (shutdown_clean, clean_checkpoint_id): (i64, Option<i64>) = conn
            .query_row(
                "SELECT shutdown_clean, clean_checkpoint_id
                 FROM mux_sessions WHERE session_id = ?1",
                [session_id.as_str()],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("load exact clean receipt binding");
        assert_eq!(shutdown_clean, 1);
        assert_eq!(clean_checkpoint_id, Some(latest_checkpoint_id));
        drop(conn);
        let _ = std::fs::remove_file(&db_path);
        let _ = std::fs::remove_file(format!("{db_path_str}-wal"));
        let _ = std::fs::remove_file(format!("{db_path_str}-shm"));
    });
}

#[test]
fn prune_session_checkpoints_preserves_mux_session_when_checkpoint_count_reaches_zero() {
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!("wa_test_prune_mux_session_{}.db", std::process::id()));
        let db_path_str = db_path.to_string_lossy().to_string();
        let cx = crate::cx::for_testing();
        let storage = StorageHandle::new_with_cx(&cx, &db_path_str).await.unwrap();
        let empty_topology =
            "{\"captured_at\":0,\"schema_version\":1,\"windows\":[],\"workspace_id\":null}"
                .to_string();

        let checkpointed_session = "sess-prune-empty".to_string();
        storage
            .insert_mux_session_with_cx(
                &cx,
                checkpointed_session.clone(),
                empty_topology.clone(),
                "test-ft-version".to_string(),
                Some("host-prune".to_string()),
            )
            .await
            .unwrap();
        storage
            .insert_session_checkpoint_with_cx(
                &cx,
                checkpointed_session.clone(),
                "periodic".to_string(),
                empty_topology.clone(),
                None,
                Vec::new(),
            )
            .await
            .unwrap();

        let pending_session = "sess-prune-pending".to_string();
        storage
            .insert_mux_session_with_cx(
                &cx,
                pending_session.clone(),
                empty_topology.clone(),
                "test-ft-version".to_string(),
                Some("host-prune".to_string()),
            )
            .await
            .unwrap();

        let receipt_session = "sess-prune-receipt".to_string();
        storage
            .insert_mux_session_with_cx(
                &cx,
                receipt_session.clone(),
                empty_topology.clone(),
                "test-ft-version".to_string(),
                Some("host-prune".to_string()),
            )
            .await
            .unwrap();
        storage
            .insert_session_checkpoint_with_cx(
                &cx,
                receipt_session.clone(),
                "periodic".to_string(),
                empty_topology.clone(),
                None,
                Vec::new(),
            )
            .await
            .unwrap();

        // Seed a role-specific restore receipt through an independent test
        // connection. Production restore code computes this same v2 witness
        // inside its transaction; this fixture isolates snapshot retention.
        let receipt_at = i64::MAX - 1;
        let receipt_metadata = "{\"old_to_new\":{}}";
        let receipt_conn = rusqlite::Connection::open(&db_path).expect("open receipt seeder");
        receipt_conn
            .execute_batch("PRAGMA foreign_keys = ON")
            .expect("enable receipt seeder foreign keys");
        receipt_conn
            .execute(
                "INSERT INTO session_checkpoints
                 (session_id, checkpoint_at, checkpoint_type, state_hash,
                  pane_count, total_bytes, metadata_json, checkpoint_role,
                  topology_json)
                 VALUES (?1, ?2, 'startup', 'pending:rst2', 0, 0, ?3,
                         'restore_receipt', NULL)",
                rusqlite::params![receipt_session.as_str(), receipt_at, receipt_metadata],
            )
            .expect("insert restore receipt fixture");
        let restore_receipt_id = receipt_conn.last_insert_rowid();
        let restore_receipt_hash = checkpoint_witness(
            crate::checkpoint_witness::CHECKPOINT_ROLE_RESTORE_RECEIPT,
            &receipt_session,
            restore_receipt_id,
            receipt_at,
            "startup",
            0,
            0,
            Some(receipt_metadata),
            None,
            &[],
        )
        .expect("compute restore receipt witness");
        receipt_conn
            .execute(
                "UPDATE session_checkpoints SET state_hash = ?1 WHERE id = ?2",
                rusqlite::params![restore_receipt_hash, restore_receipt_id],
            )
            .expect("finalize restore receipt witness");
        receipt_conn
            .execute(
                "INSERT INTO session_checkpoints
                 (session_id, checkpoint_at, checkpoint_type, state_hash,
                  pane_count, total_bytes, metadata_json, checkpoint_role,
                  topology_json)
                 VALUES (?1, ?2, 'shutdown', 'pending:snp2', 0, 0, NULL,
                         'snapshot', ?3)",
                rusqlite::params![receipt_session.as_str(), i64::MAX, empty_topology.as_str()],
            )
            .expect("insert bound snapshot fixture");
        let bound_snapshot_id = receipt_conn.last_insert_rowid();
        let bound_snapshot_hash = checkpoint_witness(
            CHECKPOINT_ROLE_SNAPSHOT,
            &receipt_session,
            bound_snapshot_id,
            i64::MAX,
            "shutdown",
            0,
            0,
            None,
            Some(&empty_topology),
            &[],
        )
        .expect("compute bound snapshot witness");
        receipt_conn
            .execute(
                "UPDATE session_checkpoints SET state_hash = ?1 WHERE id = ?2",
                rusqlite::params![bound_snapshot_hash, bound_snapshot_id],
            )
            .expect("finalize bound snapshot witness");
        receipt_conn
            .execute(
                "UPDATE mux_sessions
                 SET last_checkpoint_at = ?2,
                     shutdown_clean = 1,
                     clean_checkpoint_id = ?3
                 WHERE session_id = ?1",
                rusqlite::params![receipt_session.as_str(), i64::MAX, bound_snapshot_id],
            )
            .expect("bind exact snapshot receipt fixture");
        drop(receipt_conn);

        let pruned = storage
            .prune_session_checkpoints_with_cx(&cx, checkpointed_session.clone(), 0)
            .await
            .unwrap();
        assert_eq!(pruned, 1, "retention=0 should prune the only checkpoint");

        let receipt_pruned = storage
            .prune_session_checkpoints_with_cx(&cx, receipt_session.clone(), 0)
            .await
            .unwrap();
        assert_eq!(
            receipt_pruned, 2,
            "snapshot retention should prune both snapshots but not the restore receipt"
        );

        let pending_pruned = storage
            .prune_session_checkpoints_with_cx(&cx, pending_session.clone(), 0)
            .await
            .unwrap();
        assert_eq!(
            pending_pruned, 0,
            "session with no checkpoints should not report checkpoint pruning"
        );

        storage.shutdown_with_cx(&cx).await.unwrap();

        let conn = rusqlite::Connection::open(&db_path).expect("open sqlite connection");
        let checkpointed_session_rows: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM mux_sessions WHERE session_id = ?1",
                rusqlite::params![checkpointed_session],
                |row| row.get(0),
            )
            .expect("count pruned mux session");
        assert_eq!(
            checkpointed_session_rows, 1,
            "checkpoint pruning has no authority to delete its mux-session anchor"
        );
        let checkpointed_authority: (Option<i64>, i64, Option<i64>) = conn
            .query_row(
                "SELECT last_checkpoint_at, shutdown_clean, clean_checkpoint_id
                 FROM mux_sessions WHERE session_id = ?1",
                [checkpointed_session.as_str()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("load checkpoint-pruned mux-session authority");
        assert_eq!(checkpointed_authority, (None, 0, None));

        let pending_session_rows: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM mux_sessions WHERE session_id = ?1",
                rusqlite::params![pending_session],
                |row| row.get(0),
            )
            .expect("count pending mux session");
        assert_eq!(
            pending_session_rows, 1,
            "mux session inserted before its first checkpoint must not be reclaimed"
        );

        let (receipt_session_rows, receipt_clean, bound_receipt): (i64, i64, Option<i64>) = conn
            .query_row(
                "SELECT 1, shutdown_clean, clean_checkpoint_id
                 FROM mux_sessions WHERE session_id = ?1",
                [receipt_session.as_str()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("load receipt-backed session");
        assert_eq!(receipt_session_rows, 1);
        assert_eq!(receipt_clean, 0);
        assert_eq!(bound_receipt, None);
        let remaining_receipt_role: String = conn
            .query_row(
                "SELECT checkpoint_role FROM session_checkpoints WHERE id = ?1",
                [restore_receipt_id],
                |row| row.get(0),
            )
            .expect("restore receipt must survive snapshot retention");
        assert_eq!(remaining_receipt_role, "restore_receipt");

        let remaining_checkpoints: i64 = conn
            .query_row("SELECT COUNT(*) FROM session_checkpoints", [], |row| {
                row.get(0)
            })
            .expect("count remaining checkpoints");
        assert_eq!(remaining_checkpoints, 1);

        drop(conn);
        let _ = std::fs::remove_file(&db_path);
        let _ = std::fs::remove_file(format!("{db_path_str}-wal"));
        let _ = std::fs::remove_file(format!("{db_path_str}-shm"));
    });
}

/// ft-xbnl0.2.3 Cx-first: tick 142 token-lifecycle clusters —
/// 4 new storage cx-first siblings across two related clusters:
/// approval-token-code lookup/consume, and prepared-plan insert/consume.
/// `get_approval_token_by_code_with_cx`,
/// `consume_approval_token_by_code_with_cx`,
/// `insert_prepared_plan_with_cx`, `consume_prepared_plan_with_cx`.
#[test]
fn storage_tick142_token_lifecycle_clusters_roundtrip() {
    run_storage_async_test(async {
        let temp_dir = std::env::temp_dir();
        let db_path = temp_dir.join(format!("wa_test_tick142_{}.db", std::process::id()));
        let db_path_str = db_path.to_string_lossy().to_string();
        let cx = crate::cx::for_testing();
        let storage = StorageHandle::new_with_cx(&cx, &db_path_str).await.unwrap();

        // Seed pane for FK constraints on both approval_tokens and
        // prepared_plans (both reference pane_id).
        let pane = PaneRecord {
            pane_id: 9,
            pane_uuid: None,
            domain: "local".to_string(),
            window_id: None,
            tab_id: None,
            title: Some("tick142".to_string()),
            cwd: None,
            tty_name: None,
            first_seen_at: 1_700_000_000_000,
            last_seen_at: 1_700_000_000_000,
            observed: true,
            ignore_reason: None,
            last_decision_at: None,
        };
        storage.upsert_pane_with_cx(&cx, pane).await.unwrap();

        // ---- approval-token-code cluster ----
        let approval_record = ApprovalTokenRecord {
            id: 0,
            code_hash: "code-hash-tick142".to_string(),
            created_at: 1_700_000_000_000,
            expires_at: 4_100_000_000_000,
            used_at: None,
            workspace_id: "ws-tick142".to_string(),
            action_kind: "send_text".to_string(),
            pane_id: Some(9),
            action_fingerprint: "fp-tick142".to_string(),
            plan_hash: None,
            plan_version: None,
            risk_summary: None,
        };
        let token_id = storage
            .insert_approval_token_with_cx(&cx, approval_record)
            .await
            .unwrap();
        assert!(token_id > 0);
        let active_count = storage
            .count_active_approvals_with_cx(&cx, "ws-tick142", 1_700_000_000_500)
            .await
            .unwrap();
        assert_eq!(active_count, 1);
        assert!(
            storage
                .has_active_approval_for_scope_blocking(
                    "ws-tick142",
                    "send_text",
                    Some(9),
                    "fp-tick142",
                    1_700_000_000_500,
                )
                .unwrap()
        );

        // 1. get_approval_token_by_code_with_cx — unused, should return Some.
        let fetched = storage
            .get_approval_token_by_code_with_cx(&cx, "code-hash-tick142", "ws-tick142")
            .await
            .unwrap()
            .expect("approval token should exist before consume");
        assert_eq!(fetched.workspace_id, "ws-tick142");
        assert!(fetched.used_at.is_none());
        let fetched_by_hash = storage
            .get_approval_token_with_cx(&cx, "code-hash-tick142")
            .await
            .unwrap()
            .expect("approval token should be found by hash before consume");
        assert_eq!(fetched_by_hash.id, fetched.id);

        // 2. consume_approval_token_by_code_with_cx — should return the token
        //    and mark it used. Repeat consume should now return None.
        let consumed = storage
            .consume_approval_token_by_code_with_cx(&cx, "code-hash-tick142", "ws-tick142")
            .await
            .unwrap()
            .expect("approval token should be consumable once");
        assert_eq!(consumed.code_hash, "code-hash-tick142");
        let after_consume = storage
            .consume_approval_token_by_code_with_cx(&cx, "code-hash-tick142", "ws-tick142")
            .await
            .unwrap();
        assert!(
            after_consume.is_none(),
            "approval token can only be consumed once"
        );
        let active_after_consume = storage
            .count_active_approvals_with_cx(&cx, "ws-tick142", 1_700_000_000_600)
            .await
            .unwrap();
        assert_eq!(active_after_consume, 0);
        assert!(
            !storage
                .has_active_approval_for_scope_blocking(
                    "ws-tick142",
                    "send_text",
                    Some(9),
                    "fp-tick142",
                    1_700_000_000_600,
                )
                .unwrap()
        );

        let scoped_approval_record = ApprovalTokenRecord {
            id: 0,
            code_hash: "scoped-code-hash-tick142".to_string(),
            created_at: 1_700_000_000_000,
            expires_at: 4_100_000_000_000,
            used_at: None,
            workspace_id: "ws-tick142".to_string(),
            action_kind: "send_text".to_string(),
            pane_id: Some(9),
            action_fingerprint: "fp-scoped-tick142".to_string(),
            plan_hash: None,
            plan_version: None,
            risk_summary: None,
        };
        let scoped_token_id = storage
            .insert_approval_token_with_cx(&cx, scoped_approval_record)
            .await
            .unwrap();
        assert!(scoped_token_id > 0);
        let wrong_scope = storage
            .consume_approval_token_with_cx(
                &cx,
                "scoped-code-hash-tick142",
                "ws-tick142",
                "send_text",
                Some(9),
                "wrong-fingerprint",
            )
            .await
            .unwrap();
        assert!(
            wrong_scope.is_none(),
            "scope mismatch must not consume approval token"
        );
        let scoped_consumed = storage
            .consume_approval_token_with_cx(
                &cx,
                "scoped-code-hash-tick142",
                "ws-tick142",
                "send_text",
                Some(9),
                "fp-scoped-tick142",
            )
            .await
            .unwrap()
            .expect("scoped approval token should be consumable once");
        assert_eq!(scoped_consumed.id, scoped_token_id);
        assert!(scoped_consumed.used_at.is_some());
        let scoped_after = storage
            .consume_approval_token_with_cx(
                &cx,
                "scoped-code-hash-tick142",
                "ws-tick142",
                "send_text",
                Some(9),
                "fp-scoped-tick142",
            )
            .await
            .unwrap();
        assert!(
            scoped_after.is_none(),
            "scoped approval token can only be consumed once"
        );

        // ---- prepared-plan cluster ----
        let plan = PreparedPlanRecord {
            plan_id: "plan-tick142".to_string(),
            plan_hash: "hash-tick142".to_string(),
            workspace_id: "ws-tick142".to_string(),
            action_kind: "send_text".to_string(),
            pane_id: Some(9),
            pane_uuid: None,
            params_json: None,
            plan_json: "{}".to_string(),
            requires_approval: false,
            created_at: 1_700_000_000_000,
            expires_at: 4_100_000_000_000,
            consumed_at: None,
        };
        storage
            .insert_prepared_plan_with_cx(&cx, plan)
            .await
            .unwrap();
        let plan_fetched = storage
            .get_prepared_plan_with_cx(&cx, "plan-tick142")
            .await
            .unwrap()
            .expect("prepared plan should exist before consume");
        assert_eq!(plan_fetched.plan_hash, "hash-tick142");

        // 3. consume_prepared_plan_with_cx — first call returns the record,
        //    second returns None since the plan is now consumed.
        let plan_consumed = storage
            .consume_prepared_plan_with_cx(&cx, "plan-tick142", 1_700_000_000_500)
            .await
            .unwrap()
            .expect("prepared plan should be consumable once");
        assert_eq!(plan_consumed.plan_id, "plan-tick142");
        let plan_after = storage
            .consume_prepared_plan_with_cx(&cx, "plan-tick142", 1_700_000_000_600)
            .await
            .unwrap();
        assert!(
            plan_after.is_none(),
            "prepared plan should only be consumed once"
        );

        storage.shutdown_with_cx(&cx).await.unwrap();
        let _ = std::fs::remove_file(&db_path);
        let _ = std::fs::remove_file(format!("{db_path_str}-wal"));
        let _ = std::fs::remove_file(format!("{db_path_str}-shm"));
    });
}

