        // 1. list_active_mutes_with_cx — empty on fresh DB.
        let mutes = storage.list_active_mutes_with_cx(&cx, ts).await.unwrap();
        assert!(mutes.is_empty());

        // 2. count_segments_before_with_cx — 0 on empty DB.
