        // 4. count_usage_metrics_before_with_cx — 0.
        let usage = storage
            .count_usage_metrics_before_with_cx(&cx, future_ts)
            .await
            .unwrap();
        assert_eq!(usage, 0);

        // 5. get_action_undo_with_cx — None for nonexistent.
        let undo = storage.get_action_undo_with_cx(&cx, 999_999).await.unwrap();
