#[test]
fn semantic_budget_poison_recovery_retires_cache_authority_and_transient_state() {
    let state = Arc::new(Mutex::new(SemanticBudgetState::new(
        SemanticBudgetConfig::default(),
    )));
    let poisoned = Arc::clone(&state);
    let join = std::thread::spawn(move || {
        let mut guard = poisoned.lock().expect("lock semantic state");
        guard.backoff_until_ms = Some(i64::MAX);
        guard.rate_window_started_at_ms = 42;
        guard.rate_window_queries = 9;
        let generation = Arc::clone(&guard.generation);
        let _ = guard.cache.put(
            SemanticQueryCacheKey {
                embedder_id: "poison-test".to_owned(),
                pane_id: None,
                zone_type: None,
                since: None,
                until: None,
                limit: 1,
                query_vector_hash: 1,
                query_vector_len: 1,
            },
            CachedSemanticHits {
                hits: Vec::new(),
                expires_at_ms: i64::MAX,
                generation,
            },
        );
        panic!("intentional semantic budget poison");
    });
    assert!(join.join().is_err());
    assert!(state.is_poisoned());

    let guard = lock_semantic_budget_state(&state);

    assert!(!state.is_poisoned());
    assert!(guard.cache.is_empty());
    assert_eq!(guard.backoff_until_ms, None);
    assert_eq!(guard.rate_window_started_at_ms, 0);
    assert_eq!(guard.rate_window_queries, 0);
    assert_eq!(guard.metrics.semantic_state_poison_recoveries, 1);
}

#[test]
fn writer_join_authority_timeout_after_transfer_retains_terminal_receipt() {
    let (release_tx, release_rx) = std::sync::mpsc::channel::<()>();
    let native_writer = thread::spawn(move || {
        release_rx
            .recv()
            .expect("test controls native writer release");
    });
    let authority = Arc::new(WriterJoinAuthority::new(native_writer));
    let join_owner_authority = Arc::clone(&authority);
    let join_owner = thread::spawn(move || {
        join_owner_authority.drive(std::time::Duration::from_secs(5))
    });

    let transfer_deadline = Instant::now() + std::time::Duration::from_secs(5);
    loop {
        let transferred = matches!(
            &*authority.state.lock().expect("writer join authority lock"),
            WriterJoinState::Joining
        );
        if transferred {
            break;
        }
        assert!(
            Instant::now() < transfer_deadline,
            "join owner must transfer Pending to Joining"
        );
        thread::yield_now();
    }

    assert_eq!(
        authority.drive(std::time::Duration::ZERO),
        WriterJoinDriveOutcome::InProgress,
        "a bounded waiter may time out without consuming the in-flight authority"
    );
    assert_eq!(authority.outcome().unwrap(), None);

    release_tx.send(()).expect("release native writer");
    assert_eq!(
        join_owner.join().expect("join authority driver"),
        WriterJoinDriveOutcome::Completed(WriterJoinOutcome::Joined)
    );
    assert_eq!(
        authority.outcome().unwrap(),
        Some(WriterJoinOutcome::Joined),
        "the join result must persist independently of the timed-out waiter"
    );
    assert_eq!(
        authority.drive(std::time::Duration::ZERO),
        WriterJoinDriveOutcome::Completed(WriterJoinOutcome::Joined),
        "later callers must observe the retained receipt"
    );
}

#[test]
fn writer_join_authority_drop_before_blocking_start_retains_pending_handle() {
    use crate::runtime_async::CompatRuntime as _;
    use std::future::Future as _;
    use std::task::Poll;

    let runtime = crate::runtime_async::RuntimeBuilder::current_thread()
        .max_blocking_threads(1)
        .build()
        .expect("one-worker test runtime");
    runtime.block_on(async {
        let pool = crate::runtime_async::current_runtime_handle()
            .and_then(|handle| handle.blocking_handle())
            .expect("test runtime must expose its blocking pool");
        let (blocker_entered_tx, blocker_entered_rx) = std::sync::mpsc::sync_channel(1);
        let (release_blocker_tx, release_blocker_rx) = std::sync::mpsc::sync_channel(1);
        let blocker = pool.spawn(move || {
            blocker_entered_tx
                .send(())
                .expect("announce occupied blocking worker");
            release_blocker_rx
                .recv()
                .expect("release occupied blocking worker");
        });
        blocker_entered_rx
            .recv_timeout(std::time::Duration::from_secs(5))
            .expect("blocking worker did not enter its gate");

        let (release_writer_tx, release_writer_rx) = std::sync::mpsc::channel::<()>();
        let native_writer = thread::spawn(move || {
            release_writer_rx
                .recv()
                .expect("test controls native writer release");
        });
        let authority = Arc::new(WriterJoinAuthority::new(native_writer));
        let queued_authority = Arc::clone(&authority);
        let cx = crate::cx::for_testing();
        let mut queued = Box::pin(crate::runtime_async::spawn_blocking_with_cx(
            &cx,
            move || queued_authority.drive(std::time::Duration::from_secs(5)),
        ));
        let first_poll = std::future::poll_fn(|poll_cx| {
            Poll::Ready(queued.as_mut().poll(poll_cx))
        })
        .await;
        assert!(
            matches!(first_poll, Poll::Pending),
            "join settlement must queue behind the occupied worker"
        );
        for _ in 0..1_000 {
            if pool.pending_count() == 1 {
                break;
            }
            crate::runtime_async::task::yield_now().await;
        }
        assert_eq!(pool.pending_count(), 1, "join settlement must be queued");

        drop(queued);
        release_blocker_tx
            .send(())
            .expect("release occupied blocking worker");
        assert!(
            blocker.wait_timeout(std::time::Duration::from_secs(5)),
            "occupied blocking worker did not finish"
        );
        for _ in 0..1_000 {
            if pool.pending_count() == 0 {
                break;
            }
            crate::runtime_async::task::yield_now().await;
        }
        assert_eq!(pool.pending_count(), 0, "cancelled queued join must retire");
        assert!(
            matches!(
                &*authority.state.lock().expect("writer join authority lock"),
                WriterJoinState::Pending(_)
            ),
            "dropping queued-but-unstarted settlement must retain the native handle"
        );

        release_writer_tx.send(()).expect("release native writer");
        assert_eq!(
            authority.drive(std::time::Duration::from_secs(5)),
            WriterJoinDriveOutcome::Completed(WriterJoinOutcome::Joined)
        );
    });
}

#[test]
fn writer_join_authority_panic_receipt_is_persistent() {
    let native_writer = thread::spawn(|| panic!("synthetic writer panic"));
    let authority = WriterJoinAuthority::new(native_writer);

    assert_eq!(
        authority.drive(std::time::Duration::from_secs(5)),
        WriterJoinDriveOutcome::Completed(WriterJoinOutcome::Panicked)
    );
    assert_eq!(
        authority.outcome().unwrap(),
        Some(WriterJoinOutcome::Panicked)
    );
    assert_eq!(
        authority.drive(std::time::Duration::ZERO),
        WriterJoinDriveOutcome::Completed(WriterJoinOutcome::Panicked),
        "a retry must never reinterpret a panicked join as clean"
    );
}

#[test]
fn storage_shutdown_with_cx_is_idempotent_after_clean_join() {
    run_storage_async_test(async {
        let directory = tempfile::tempdir().expect("temporary directory");
        let db_path = directory.path().join("shutdown-idempotent.sqlite3");
        let storage = StorageHandle::new(&db_path.to_string_lossy()).await.unwrap();

        let first_cx = crate::cx::for_testing();
        storage.shutdown_with_cx(&first_cx).await.unwrap();
        assert_eq!(
            storage.completed_writer_join_outcome().unwrap(),
            Some(WriterJoinOutcome::Joined),
            "the first clean shutdown must retain an authoritative native join receipt"
        );

        let second_cx = crate::cx::for_testing();
        storage.shutdown_with_cx(&second_cx).await.unwrap();
        assert_eq!(
            storage.write_tx.terminal_state.load(AtomicOrdering::Acquire),
            WRITER_TERMINAL_CLOSED_CLEANLY,
            "a repeated shutdown must report the retained clean terminal state"
        );
    });
}

